/* DAWAH X — ahmad, অধ্যায় 8 · খণ্ড 8 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][8]=[[1401,1401,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏وَسُفْيَانُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏وَقَالَ ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏بَعْضِ ‏ ‏آلِ ‏ ‏سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهِ يَعُودُهُ وَهُوَ مَرِيضٌ ‏ ‏بِمَكَّةَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ أُوصِي بِمَالِي كُلِّهِ قَالَ لَا قُلْتُ ‏ ‏فَبِالشَّطْرِ ‏ ‏قَالَ لَا قُلْتُ فَبِالثُّلُثِ قَالَ الثُّلُثُ وَالثُّلُثُ كَبِيرٌ ‏ ‏أَوْ كَثِيرٌ ‏ ‏إِنَّكَ ‏ ‏أَنْ تَدَعَ وَارِثَكَ غَنِيًّا خَيْرٌ مِنْ أَنْ تَدَعَهُ فَقِيرًا ‏ ‏يَتَكَفَّفُ ‏ ‏النَّاسَ وَإِنَّكَ مَهْمَا أَنْفَقْتَ عَلَى أَهْلِكَ مِنْ نَفَقَةٍ فَإِنَّكَ تُؤْجَرُ فِيهَا حَتَّى اللُّقْمَةَ تَرْفَعُهَا إِلَى ‏ ‏فِي امْرَأَتِكَ ‏ ‏قَالَ ‏ ‏وَلَمْ يَكُنْ لَهُ يَوْمَئِذٍ إِلَّا ابْنَةٌ فَذَكَرَ ‏ ‏سَعْدٌ ‏ ‏الْهِجْرَةَ ‏ ‏فَقَالَ ‏ ‏يَرْحَمُ اللَّهُ ‏ ‏ابْنَ عَفْرَاءَ ‏ ‏وَلَعَلَّ اللَّهَ يَرْفَعُكَ حَتَّى يَنْتَفِعَ بِكَ قَوْمٌ وَيُضَرَّ بِكَ آخَرُونَ ‏","","",""],[1402,1402,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ مِخْرَاقٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عَبَايَةَ ‏ ‏عَنْ ‏ ‏مَوْلًى ‏ ‏لِسَعْدٍ ‏ ‏أَنَّ ‏ ‏سَعْدًا ‏ ‏سَمِعَ ابْنًا لَهُ يَدْعُو وَهُوَ يَقُولُ اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَنَعِيمَهَا وَإِسْتَبْرَقَهَا وَنَحْوًا مِنْ هَذَا وَأَعُوذُ بِكَ مِنْ النَّارِ وَسَلَاسِلِهَا وَأَغْلَالِهَا فَقَالَ لَقَدْ سَأَلْتَ اللَّهَ خَيْرًا كَثِيرًا وَتَعَوَّذْتَ بِاللَّهِ مِنْ شَرٍّ كَثِيرٍ وَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّهُ ‏ ‏سَيَكُونُ قَوْمٌ يَعْتَدُونَ فِي الدُّعَاءِ وَقَرَأَ هَذِهِ الْآيَةَ ‏ { ‏ادْعُوا رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً إِنَّهُ لَا يُحِبُّ الْمُعْتَدِينَ ‏} ‏وَإِنَّ حَسْبَكَ أَنْ تَقُولَ اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ وَأَعُوذُ بِكَ مِنْ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ ‏","","",""],[1403,1403,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَلِّمُ عَنْ يَمِينِهِ حَتَّى يُرَى بَيَاضُ خَدِّهِ وَعَنْ يَسَارِهِ حَتَّى يُرَى بَيَاضُ خَدِّهِ ‏","","",""],[1404,1404,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهِ ‏ ‏بِمَكَّةَ ‏ ‏وَهُوَ مَرِيضٌ فَقَالَ إِنَّهُ لَيْسَ لِي إِلَّا ابْنَةٌ وَاحِدَةٌ ‏ ‏فَأُوصِي بِمَالِي كُلِّهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا قَالَ فَأُوصِي بِنِصْفِهِ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا قَالَ فَأُوصِي بِثُلُثِهِ قَالَ الثُّلُثُ وَالثُّلُثُ كَبِيرٌ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي غَلَّابٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهِ ‏ ‏فَذَكَرَ مِثْلَهُ ‏ ‏و قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏كَثِيرٌ ‏ ‏يَعْنِي وَالثُّلُثُ ‏","","",""],[1405,1405,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏الْمَعْنَى ‏ ‏قَالَا أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْعَيْزَارِ بْنِ حُرَيْثٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَجِبْتُ مِنْ قَضَاءِ اللَّهِ عَزَّ وَجَلَّ لِلْمُؤْمِنِ إِنْ أَصَابَهُ خَيْرٌ حَمِدَ رَبَّهُ وَشَكَرَ وَإِنْ أَصَابَتْهُ مُصِيبَةٌ حَمِدَ رَبَّهُ وَصَبَرَ الْمُؤْمِنُ يُؤْجَرُ فِي كُلِّ شَيْءٍ حَتَّى فِي اللُّقْمَةِ يَرْفَعُهَا إِلَى ‏ ‏فِي امْرَأَتِهِ ‏","","",""],[1406,1406,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏جَاءَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعُودُهُ وَهُوَ ‏ ‏بِمَكَّةَ ‏ ‏وَهُوَ يَكْرَهُ أَنْ يَمُوتَ بِالْأَرْضِ الَّتِي هَاجَرَ مِنْهَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْحَمُ اللَّهُ ‏ ‏سَعْدَ ابْنَ عَفْرَاءَ ‏ ‏يَرْحَمُ اللَّهُ ‏ ‏سَعْدَ ابْنَ عَفْرَاءَ ‏ ‏وَلَمْ يَكُنْ لَهُ إِلَّا ابْنَةٌ وَاحِدَةٌ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُوصِي بِمَالِي كُلِّهِ قَالَ لَا قَالَ فَالنِّصْفُ قَالَ لَا قَالَ فَالثُّلُثُ قَالَ ‏ ‏الثُّلُثُ وَالثُّلُثُ كَثِيرٌ إِنَّكَ أَنْ تَدَعَ وَرَثَتَكَ أَغْنِيَاءَ خَيْرٌ مِنْ أَنْ تَدَعَهُمْ عَالَةً ‏ ‏يَتَكَفَّفُونَ ‏ ‏النَّاسَ فِي أَيْدِيهِمْ وَإِنَّكَ مَهْمَا أَنْفَقْتَ مِنْ نَفَقَةٍ فَإِنَّهَا ‏ ‏صَدَقَةٌ ‏ ‏حَتَّى اللُّقْمَةَ تَرْفَعُهَا إِلَى ‏ ‏فِي امْرَأَتِكَ وَلَعَلَّ اللَّهَ أَنْ يَرْفَعَكَ فَيَنْتَفِعَ بِكَ نَاسٌ وَيُضَرَّ بِكَ آخَرُونَ ‏","","",""],[1407,1407,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏قَالَ ‏ ‏الْحَدُوا ‏ ‏لِي ‏ ‏لَحْدًا ‏ ‏وَانْصِبُوا ‏ ‏عَلَيَّ كَمَا فُعِلَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1408,1408,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏أَنْبَأَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِسَعْدِ بْنِ مَالِكٍ ‏ ‏إِنِّي أُرِيدُ أَنْ أَسْأَلَكَ عَنْ حَدِيثٍ وَأَنَا أَهَابُكَ أَنْ أَسْأَلَكَ عَنْهُ فَقَالَ لَا تَفْعَلْ يَا ابْنَ أَخِي إِذَا عَلِمْتَ أَنَّ عِنْدِي عِلْمًا فَسَلْنِي عَنْهُ وَلَا تَهَبْنِي قَالَ فَقُلْتُ قَوْلُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِعَلِيٍّ ‏ ‏حِينَ خَلَّفَهُ ‏ ‏بِالْمَدِينَةِ ‏ ‏فِي ‏ ‏غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏فَقَالَ ‏ ‏سَعْدٌ ‏ ‏خَلَّفَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلِيًّا ‏ ‏بِالْمَدِينَةِ ‏ ‏فِي ‏ ‏غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَتُخَلِّفُنِي فِي الْخَالِفَةِ فِي النِّسَاءِ وَالصِّبْيَانِ فَقَالَ ‏ ‏أَمَا ‏ ‏تَرْضَى أَنْ تَكُونَ مِنِّي بِمَنْزِلَةِ ‏ ‏هَارُونَ ‏ ‏مِنْ ‏ ‏مُوسَى ‏ ‏قَالَ بَلَى يَا رَسُولَ اللَّهِ قَالَ فَأَدْبَرَ ‏ ‏عَلِيٌّ ‏ ‏مُسْرِعًا كَأَنِّي أَنْظُرُ إِلَى غُبَارِ قَدَمَيْهِ يَسْطَعُ ‏ ‏وَقَدْ قَالَ ‏ ‏حَمَّادٌ ‏ ‏فَرَجَعَ ‏ ‏عَلِيٌّ ‏ ‏مُسْرِعًا ‏","","",""],[1409,1409,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنِي ‏ ‏عِكْرِمَةُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏ذُكِرَ الطَّاعُونُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏رِجْزٌ ‏ ‏أُصِيبَ بِهِ مَنْ كَانَ قَبْلَكُمْ فَإِذَا كَانَ بِأَرْضٍ فَلَا تَدْخُلُوهَا وَإِذَا كَانَ بِهَا وَأَنْتُمْ بِهَا فَلَا تَخْرُجُوا مِنْهَا ‏","","",""],[1410,1410,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْعَيْزَارِ بْنِ حُرَيْثٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَجِبْتُ لِلْمُؤْمِنِ إِذَا أَصَابَهُ خَيْرٌ حَمِدَ اللَّهَ وَشَكَرَ وَإِنْ أَصَابَتْهُ مُصِيبَةٌ حَمِدَ اللَّهَ وَصَبَرَ فَالْمُؤْمِنُ يُؤْجَرُ فِي كُلِّ أَمْرِهِ حَتَّى يُؤْجَرَ فِي اللُّقْمَةِ يَرْفَعُهَا إِلَى ‏ ‏فِي امْرَأَتِهِ ‏","","",""],[1411,1411,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَاشِدٍ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ الرَّجُلُ يَكُونُ حَامِيَةَ الْقَوْمِ أَيَكُونُ سَهْمُهُ وَسَهْمُ غَيْرِهِ سَوَاءً قَالَ ‏ ‏ثَكِلَتْكَ ‏ ‏أُمُّكَ يَا ‏ ‏ابْنَ أُمِّ سَعْدٍ ‏ ‏وَهَلْ تُرْزَقُونَ وَتُنْصَرُونَ إِلَّا بِضُعَفَائِكُمْ ‏","","",""],[1412,1412,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُصْعَبَ بْنَ سَعْدٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَعْدٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ النَّاسِ أَشَدُّ بَلَاءً فَقَالَ ‏ ‏الْأَنْبِيَاءُ ثُمَّ الْأَمْثَلُ فَالْأَمْثَلُ ‏ ‏فَيُبْتَلَى الرَّجُلُ عَلَى حَسَبِ دِينِهِ فَإِنْ كَانَ رَقِيقَ الدِّينِ ابْتُلِيَ عَلَى حَسَبِ ذَاكَ وَإِنْ كَانَ صُلْبَ الدِّينِ ابْتُلِيَ عَلَى حَسَبِ ذَاكَ قَالَ فَمَا تَزَالُ الْبَلَايَا بِالرَّجُلِ حَتَّى يَمْشِيَ فِي الْأَرْضِ وَمَا عَلَيْهِ خَطِيئَةٌ ‏","","",""],[1413,1413,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏قَالَ قَالَ ‏ ‏سَعْدُ بْنُ مَالِكٍ ‏ ‏جَمَعَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَوَيْهِ يَوْمَ ‏ ‏أُحُدٍ ‏","","",""],[1414,1414,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ ‏ ‏مَوْلَى ‏ ‏جُهَيْنَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُصْعَبَ بْنَ سَعْدٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَعْدٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَيَعْجِزُ أَحَدُكُمْ أَنْ يَكْسِبَ فِي الْيَوْمِ أَلْفَ حَسَنَةٍ قَالَ وَمَنْ يُطِيقُ ذَلِكَ قَالَ يُسَبِّحُ مِائَةَ تَسْبِيحَةٍ فَيُكْتَبُ لَهُ أَلْفُ حَسَنَةٍ ‏ ‏وَتُمْحَى عَنْهُ أَلْفُ سَيِّئَةٍ ‏","","",""],[1415,1415,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عُثْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعْدًا ‏ ‏وَهُوَ أَوَّلُ مَنْ رَمَى بِسَهْمٍ فِي سَبِيلِ اللَّهِ ‏ ‏وَأَبَا بَكْرَةَ ‏ ‏تَسَوَّرَ حِصْنَ ‏ ‏الطَّائِفِ ‏ ‏فِي نَاسٍ فَجَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَا ‏ ‏سَمِعْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ ‏ ‏مَنْ ادَّعَى إِلَى أَبٍ غَيْرِ أَبِيهِ وَهُوَ يَعْلَمُ أَنَّهُ غَيْرُ أَبِيهِ فَالْجَنَّةُ عَلَيْهِ حَرَامٌ ‏","","",""],[1416,1416,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَيْسَ بْنَ أَبِي حَازِمٍ ‏ ‏قَالَ قَالَ ‏ ‏سَعْدٌ ‏ ‏لَقَدْ ‏ ‏رَأَيْتُنِي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَابِعَ سَبْعَةٍ وَمَا لَنَا طَعَامٌ إِلَّا ‏ ‏وَرَقَ الْحُبْلَةِ ‏ ‏حَتَّى إِنَّ أَحَدَنَا لَيَضَعُ كَمَا تَضَعُ الشَّاةُ مَا يُخَالِطُهُ شَيْءٌ ثُمَّ أَصْبَحَتْ ‏ ‏بَنُو أَسَدٍ ‏ ‏يُعَزِّرُونِي ‏ ‏عَلَى الْإِسْلَامِ لَقَدْ خَسِرْتُ إِذَنْ وَضَلَّ سَعْيِي ‏","","",""],[1417,1417,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عُثْمَانَ النَّهْدِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ادَّعَى إِلَى غَيْرِ أَبِيهِ وَهُوَ يَعْلَمُ فَالْجَنَّةُ عَلَيْهِ حَرَامٌ ‏","","",""],[1418,1418,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حُمَيْدٍ ‏ ‏أَخْبَرَنِي ‏ ‏إِسْمَاعِيلُ بْنُ مُحَمَّدِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏سَعْدُ ‏ ‏قُمْ فَأَذِّنْ ‏ ‏بِمِنًى ‏ ‏إِنَّهَا أَيَّامُ أَكْلٍ وَشُرْبٍ وَلَا صَوْمَ فِيهَا ‏","","",""],[1419,1419,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏قَالَ قَالَ ‏ ‏سَعْدٌ ‏ ‏فِيَّ سَنَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الثُّلُثَ أَتَانِي يَعُودُنِي قَالَ فَقَالَ لِي أَوْصَيْتَ قَالَ قُلْتُ نَعَمْ ‏ ‏جَعَلْتُ مَالِي كُلَّهُ فِي الْفُقَرَاءِ وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ قَالَ لَا تَفْعَلْ قُلْتُ إِنَّ وَرَثَتِي أَغْنِيَاءُ قُلْتُ الثُّلُثَيْنِ قَالَ لَا قُلْتُ ‏ ‏فَالشَّطْرَ ‏ ‏قَالَ لَا قُلْتُ الثُّلُثَ قَالَ الثُّلُثُ وَالثُّلُثُ كَثِيرٌ ‏","","",""],[1420,1420,"","","‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏الْحَضْرَمِيِّ بْنِ لَاحِقٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏هَامَةَ ‏ ‏وَلَا عَدْوَى وَلَا ‏ ‏طِيَرَةَ ‏ ‏إِنْ يَكُنْ فَفِي الْمَرْأَةِ وَالدَّابَّةِ وَالدَّارِ ‏","","",""],[1421,1421,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏وَالضَّحَّاكَ بْنَ قَيْسٍ ‏ ‏عَامَ حَجَّ ‏ ‏مُعَاوِيَةُ بْنُ أَبِي سُفْيَانَ ‏ ‏وَهُمَا يَذْكُرَانِ ‏ ‏التَّمَتُّعَ ‏ ‏بِالْعُمْرَةِ إِلَى الْحَجِّ فَقَالَ ‏ ‏الضَّحَّاكُ ‏ ‏لَا يَصْنَعُ ذَلِكَ إِلَّا مَنْ جَهِلَ أَمْرَ اللَّهِ فَقَالَ ‏ ‏سَعْدٌ ‏ ‏بِئْسَمَا قُلْتَ يَا ابْنَ أَخِي فَقَالَ ‏ ‏الضَّحَّاكُ ‏ ‏فَإِنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏قَدْ نَهَى عَنْ ذَلِكَ فَقَالَ ‏ ‏سَعْدٌ ‏ ‏قَدْ ‏ ‏صَنَعَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَصَنَعْنَاهَا مَعَهُ ‏","","",""],[1422,1422,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏قَالَ قَالَ ‏ ‏سَعْدٌ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏سَمِعْتُ ‏ ‏سَعْدًا ‏ ‏يَقُولُ ‏ ‏سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي مِنْ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏مَنْ ادَّعَى أَبًا غَيْرَ أَبِيهِ وَهُوَ يَعْلَمُ أَنَّهُ غَيْرُ أَبِيهِ فَالْجَنَّةُ عَلَيْهِ حَرَامٌ ‏ ‏قَالَ ‏ ‏فَلَقِيتُ ‏ ‏أَبَا بَكْرَةَ ‏ ‏فَحَدَّثْتُهُ فَقَالَ ‏ ‏وَأَنَا سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي مِنْ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1423,1423,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِبْرَاهِيمَ بْنَ سَعْدٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَعْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِعَلِيٍّ ‏ ‏أَمَا ‏ ‏تَرْضَى أَنْ تَكُونَ مِنِّي بِمَنْزِلَةِ ‏ ‏هَارُونَ ‏ ‏مِنْ ‏ ‏مُوسَى ‏","","",""],[1424,1424,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏سَعْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَأَنْ يَمْتَلِئَ جَوْفُ أَحَدِكُمْ قَيْحًا ‏ ‏يَرِيهِ ‏ ‏خَيْرٌ لَهُ مِنْ أَنْ يَمْتَلِئَ شِعْرًا ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏سَمِعْتُ ‏ ‏يُونُسَ بْنَ جُبَيْرٍ ‏","","",""],[1425,1425,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ سَعْدِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَأَنْ يَمْتَلِئَ جَوْفُ أَحَدِكُمْ قَيْحًا حَتَّى ‏ ‏يَرِيَهُ ‏ ‏خَيْرٌ مِنْ أَنْ يَمْتَلِئَ شِعْرًا ‏","","",""],[1426,1426,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏فِي الطَّاعُونِ إِذَا وَقَعَ بِأَرْضٍ فَلَا تَدْخُلُوهَا وَإِذَا كُنْتُمْ بِهَا فَلَا تَفِرُّوا مِنْهُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَحَدَّثَنِي ‏ ‏هِشَامٌ أَبُو بَكْرٍ ‏ ‏أَنَّهُ ‏ ‏عِكْرِمَةُ بْنُ خَالِدٍ ‏","","",""],[1427,1427,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِسَعْدِ بْنِ مَالِكٍ ‏ ‏إِنَّكَ إِنْسَانٌ فِيكَ حِدَّةٌ وَأَنَا أُرِيدُ أَنْ أَسْأَلَكَ قَالَ مَا هُوَ قَالَ قُلْتُ حَدِيثُ ‏ ‏عَلِيٍّ ‏ ‏قَالَ فَقَالَ إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَلِيٍّ ‏ ‏أَمَا ‏ ‏تَرْضَى أَنْ تَكُونَ مِنِّي بِمَنْزِلَةِ ‏ ‏هَارُونَ ‏ ‏مِنْ ‏ ‏مُوسَى ‏ ‏قَالَ رَضِيتُ ثُمَّ قَالَ بَلَى بَلَى ‏","","",""],[1428,1428,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي عَوْنٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏وَبَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو عَوْنٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏لِسَعْدٍ ‏ ‏شَكَاكَ النَّاسُ فِي كُلِّ شَيْءٍ حَتَّى فِي الصَّلَاةِ قَالَ أَمَّا أَنَا ‏ ‏فَأَمُدُّ ‏ ‏مِنْ الْأُولَيَيْنِ ‏ ‏وَأَحْذِفُ ‏ ‏مِنْ الْأُخْرَيَيْنِ وَلَا ‏ ‏آلُو ‏ ‏مَا اقْتَدَيْتُ بِهِ مِنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏ذَاكَ الظَّنُّ بِكَ ‏ ‏أَوْ ظَنِّي بِكَ ‏","","",""],[1429,1429,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏فِطْرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَرِيكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الرُّقَيْمِ الْكِنَانِيِّ ‏ ‏قَالَ ‏ ‏خَرَجْنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏زَمَنَ الْجَمَلِ فَلَقِيَنَا ‏ ‏سَعْدُ بْنُ مَالِكٍ ‏ ‏بِهَا فَقَالَ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسَدِّ الْأَبْوَابِ الشَّارِعَةِ فِي الْمَسْجِدِ وَتَرْكِ بَابِ ‏ ‏عَلِيٍّ ‏","","",""],[1430,1430,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَنْبَأَنَا ‏ ‏لَيْثٌ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي مُلَيْكَةَ الْقُرَشِيُّ ثُمَّ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي نَهِيكٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَيْسَ مِنَّا مَنْ لَمْ ‏ ‏يَتَغَنَّ ‏ ‏بِالْقُرْآنِ ‏","","",""],[1431,1431,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَنْبَأَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ ‏ ‏يَطْرُقَ ‏ ‏الرَّجُلُ أَهْلَهُ بَعْدَ صَلَاةِ الْعِشَاءِ ‏","","",""],[1432,1432,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَنْبَأَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏أَرَادَ ‏ ‏عُثْمَانُ بْنُ مَظْعُونٍ ‏ ‏أَنْ ‏ ‏يَتَبَتَّلَ ‏ ‏فَنَهَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَوْ أَجَازَ ذَلِكَ لَهُ ‏ ‏لَاخْتَصَيْنَا ‏","","",""],[1433,1433,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏مَوْلَى ‏ ‏الْأَسْوَدِ بْنِ سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي عَيَّاشٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الرُّطَبِ بِالتَّمْرِ فَقَالَ ‏ ‏أَلَيْسَ يَنْقُصُ الرُّطَبُ إِذَا يَبِسَ قَالُوا بَلَى فَكَرِهَهُ ‏","","",""],[1434,1434,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَامِرُ بْنُ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَقْبَلْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى مَرَرْنَا عَلَى مَسْجِدِ ‏ ‏بَنِي مُعَاوِيَةَ ‏ ‏فَدَخَلَ فَصَلَّى رَكْعَتَيْنِ وَصَلَّيْنَا مَعَهُ وَنَاجَى رَبَّهُ عَزَّ وَجَلَّ طَوِيلًا قَالَ ‏ ‏سَأَلْتُ رَبِّي عَزَّ وَجَلَّ ثَلَاثًا سَأَلْتُهُ أَنْ لَا يُهْلِكَ أُمَّتِي بِالْغَرَقِ فَأَعْطَانِيهَا وَسَأَلْتُهُ أَنْ لَا يُهْلِكَ أُمَّتِي ‏ ‏بِالسَّنَةِ ‏ ‏فَأَعْطَانِيهَا وَسَأَلْتُهُ أَنْ لَا يَجْعَلَ ‏ ‏بَأْسَهُمْ ‏ ‏بَيْنَهُمْ فَمَنَعَنِيهَا ‏","","",""],[1435,1435,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏وَيَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏كُنْتُ ‏ ‏أُسَمِّيهِ فَنَسِيتُ اسْمَهُ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏كَانَتْ لِي حَاجَةٌ إِلَى أَبِي ‏ ‏سَعْدٍ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو حَيَّانَ ‏ ‏عَنْ ‏ ‏مُجَمِّعٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏لِعُمَرَ بْنِ سَعْدٍ ‏ ‏إِلَى أَبِيهِ حَاجَةٌ ‏ ‏فَقَدَّمَ بَيْنَ يَدَيْ حَاجَتِهِ كَلَامًا مِمَّا يُحَدِّثُ النَّاسُ يُوصِلُونَ لَمْ يَكُنْ يَسْمَعُهُ فَلَمَّا فَرَغَ قَالَ يَا بُنَيَّ قَدْ فَرَغْتَ مِنْ كَلَامِكَ قَالَ نَعَمْ قَالَ مَا كُنْتَ مِنْ حَاجَتِكَ أَبْعَدَ وَلَا كُنْتُ فِيكَ أَزْهَدَ مِنِّي مُنْذُ سَمِعْتُ كَلَامَكَ هَذَا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَيَكُونُ قَوْمٌ يَأْكُلُونَ بِأَلْسِنَتِهِمْ كَمَا تَأْكُلُ الْبَقَرَةُ مِنْ الْأَرْضِ ‏","","",""],[1436,1436,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏قَالَ ‏ ‏شَكَا أَهْلُ ‏ ‏الْكُوفَةِ ‏ ‏سَعْدًا ‏ ‏إِلَى ‏ ‏عُمَرَ ‏ ‏فَقَالُوا لَا يُحْسِنُ ‏ ‏يُصَلِّي قَالَ فَسَأَلَهُ ‏ ‏عُمَرُ ‏ ‏فَقَالَ إِنِّي ‏ ‏أُصَلِّي بِهِمْ صَلَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْكُدُ ‏ ‏فِي الْأُولَيَيْنِ ‏ ‏وَأَحْذِفُ ‏ ‏فِي الْأُخْرَيَيْنِ قَالَ ذَلِكَ الظَّنُّ بِكَ يَا ‏ ‏أَبَا إِسْحَاقَ ‏","","",""],[1437,1437,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدُ بْنُ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِتَالُ الْمُؤْمِنِ كُفْرٌ وَسِبَابُهُ فُسُوقٌ وَلَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثَةِ أَيَّامٍ ‏","","",""],[1438,1438,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏مِنْ أَكْبَرِ الْمُسْلِمِينَ فِي الْمُسْلِمِينَ جُرْمًا رَجُلًا سَأَلَ عَنْ شَيْءٍ وَنَقَّرَ عَنْهُ حَتَّى أُنْزِلَ فِي ذَلِكَ الشَّيْءِ تَحْرِيمٌ مِنْ أَجْلِ مَسْأَلَتِهِ ‏","","",""],[1439,1439,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ سَعْدٍ ‏ ‏أَوْ غَيْرِهِ ‏ ‏أَنَّ ‏ ‏سَعْدَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ يُهِنْ ‏ ‏قُرَيْشًا ‏ ‏يُهِنْهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[1440,1440,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَعْطَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رِجَالًا وَلَمْ يُعْطِ رَجُلًا مِنْهُمْ شَيْئًا فَقَالَ ‏ ‏سَعْدٌ ‏ ‏يَا نَبِيَّ اللَّهِ أَعْطَيْتَ فُلَانًا وَفُلَانًا وَلَمْ تُعْطِ فُلَانًا شَيْئًا وَهُوَ مُؤْمِنٌ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ مُسْلِمٌ حَتَّى أَعَادَهَا ‏ ‏سَعْدٌ ‏ ‏ثَلَاثًا وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ أَوْ مُسْلِمٌ ثُمَّ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأُعْطِي رِجَالًا وَأَدَعُ مَنْ هُوَ أَحَبُّ إِلَيَّ مِنْهُمْ فَلَا أُعْطِيهِ شَيْئًا مَخَافَةَ أَنْ ‏ ‏يُكَبُّوا ‏ ‏فِي النَّارِ عَلَى وُجُوهِهِمْ ‏","","",""],[1441,1441,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَتْلِ ‏ ‏الْوَزَغِ ‏ ‏وَسَمَّاهُ فُوَيْسِقًا ‏","","",""],[1442,1442,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ فَمَرِضْتُ مَرَضًا ‏ ‏أَشْفَيْتُ ‏ ‏عَلَى الْمَوْتِ فَعَادَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ لِي مَالًا كَثِيرًا وَلَيْسَ يَرِثُنِي إِلَّا ابْنَةٌ لِي ‏ ‏أَفَأُوصِي بِثُلُثَيْ مَالِي قَالَ لَا قُلْتُ ‏ ‏بِشَطْرِ ‏ ‏مَالِي قَالَ لَا قُلْتُ فَثُلُثُ مَالِي قَالَ الثُّلُثُ وَالثُّلُثُ كَثِيرٌ إِنَّكَ يَا ‏ ‏سَعْدُ ‏ ‏أَنْ تَدَعَ وَرَثَتَكَ أَغْنِيَاءَ خَيْرٌ لَكَ مِنْ أَنْ تَدَعَهُمْ عَالَةً ‏ ‏يَتَكَفَّفُونَ ‏ ‏النَّاسَ إِنَّكَ يَا ‏ ‏سَعْدُ ‏ ‏لَنْ تُنْفِقَ نَفَقَةً تَبْتَغِي بِهَا وَجْهَ اللَّهِ تَعَالَى إِلَّا أُجِرْتَ عَلَيْهَا حَتَّى اللُّقْمَةَ تَجْعَلُهَا فِي ‏ ‏فِي امْرَأَتِكَ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ أُخَلَّفُ بَعْدَ أَصْحَابِي قَالَ إِنَّكَ لَنْ تَتَخَلَّفَ فَتَعْمَلَ عَمَلًا ‏ ‏تَبْتَغِي بِهِ وَجْهَ اللَّهِ إِلَّا ازْدَدْتَ بِهِ دَرَجَةً وَرِفْعَةً وَلَعَلَّكَ تُخَلَّفُ حَتَّى يَنْفَعَ اللَّهُ بِكَ أَقْوَامًا وَيَضُرَّ بِكَ آخَرِينَ اللَّهُمَّ ‏ ‏أَمْضِ ‏ ‏لِأَصْحَابِي هِجْرَتَهُمْ وَلَا تَرُدَّهُمْ عَلَى ‏ ‏أَعْقَابِهِمْ ‏ ‏لَكِنْ ‏ ‏الْبَائِسُ ‏ ‏سَعْدُ ابْنُ خَوْلَةَ ‏ ‏رَثَى ‏ ‏لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ مَاتَ ‏ ‏بِمَكَّةَ ‏","","",""],[1443,1443,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏لَقَدْ ‏ ‏رَدَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏عُثْمَانَ ‏ ‏التَّبَتُّلَ ‏ ‏وَلَوْ أَحَلَّهُ ‏ ‏لَاخْتَصَيْنَا ‏","","",""],[1444,1444,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ عَامِرِ بْنِ سَعْدِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ ‏ ‏لَمْ يَكُنْ نَبِيٌّ إِلَّا وَصَفَ ‏ ‏الدَّجَّالَ ‏ ‏لِأُمَّتِهِ وَلَأَصِفَنَّهُ صِفَةً لَمْ يَصِفْهَا أَحَدٌ كَانَ قَبْلِي إِنَّهُ أَعْوَرُ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَيْسَ بِأَعْوَرَ ‏","","",""],[1445,1445,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ خَالِدٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنِي عَنْ ‏ ‏يَحْيَى بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏أَنَّ الطَّاعُونَ ذُكِرَ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّهُ ‏ ‏رِجْزٌ ‏ ‏أُصِيبَ بِهِ مَنْ كَانَ قَبْلَكُمْ فَإِذَا كَانَ بِأَرْضٍ فَلَا تَدْخُلُوهَا وَإِذَا كُنْتُمْ بِأَرْضٍ وَهُوَ بِهَا فَلَا تَخْرُجُوا مِنْهَا ‏","","",""],[1446,1446,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ مَعْمَرٍ ‏ ‏قَالَ حَدَّثَ ‏ ‏عَامِرُ بْنُ سَعْدٍ ‏ ‏عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏ ‏وَهُوَ أَمِيرٌ عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏أَنَّ ‏ ‏سَعْدًا ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَكَلَ سَبْعَ تَمَرَاتِ عَجْوَةٍ مَا بَيْنَ لَابَتَيْ ‏ ‏الْمَدِينَةِ ‏ ‏حِينَ يُصْبِحُ لَمْ يَضُرَّهُ يَوْمَهُ ذَلِكَ شَيْءٌ حَتَّى يُمْسِيَ ‏ ‏قَالَ ‏ ‏فُلَيْحٌ ‏ ‏وَأَظُنُّهُ قَدْ قَالَ وَإِنْ أَكَلَهَا حِينَ يُمْسِي لَمْ يَضُرَّهُ شَيْءٌ حَتَّى يُصْبِحَ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا ‏ ‏عَامِرُ ‏ ‏انْظُرْ مَا تُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عَامِرٌ ‏ ‏وَاللَّهِ مَا كَذَبْتُ عَلَى ‏ ‏سَعْدٍ ‏ ‏وَمَا كَذَبَ ‏ ‏سَعْدٌ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1447,1447,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ الْأَسْلَمِيُّ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏جَاءَهُ ابْنُهُ ‏ ‏عَامِرٌ ‏ ‏فَقَالَ أَيْ بُنَيَّ أَفِي الْفِتْنَةِ تَأْمُرُنِي أَنْ أَكُونَ رَأْسًا لَا وَاللَّهِ حَتَّى ‏ ‏أُعْطَى سَيْفًا إِنْ ضَرَبْتُ بِهِ مُؤْمِنًا نَبَا عَنْهُ وَإِنْ ضَرَبْتُ بِهِ كَافِرًا قَتَلَهُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُحِبُّ الْغَنِيَّ ‏ ‏الْخَفِيَّ ‏ ‏التَّقِيَّ ‏","","",""],[1448,1448,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ عَنْ يَمِينِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَنْ شِمَالِهِ يَوْمَ ‏ ‏أُحُدٍ ‏ ‏رَجُلَيْنِ عَلَيْهِمَا ثِيَابٌ بِيضٌ لَمْ أَرَهُمَا قَبْلُ وَلَا بَعْدُ ‏","","",""],[1449,1449,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْعَيْزَارِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏سَعْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏عَجِبْتُ لِلْمُسْلِمِ إِذَا أَصَابَهُ خَيْرٌ حَمِدَ اللَّهَ وَشَكَرَ وَإِذَا أَصَابَتْهُ مُصِيبَةٌ ‏ ‏احْتَسَبَ ‏ ‏وَصَبَرَ الْمُسْلِمُ يُؤْجَرُ فِي كُلِّ شَيْءٍ حَتَّى فِي اللُّقْمَةِ يَرْفَعُهَا إِلَى ‏ ‏فِيهِ ‏","","",""],[1450,1450,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَعَلِيِّ بْنِ زَيْدِ بْنِ جُدْعَانَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ الْمُسَيَّبِ ‏ ‏حَدَّثَنِي ‏ ‏ابْنٌ لِسَعْدِ بْنِ مَالِكٍ ‏ ‏حَدِيثًا ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏سَعْدٍ ‏ ‏فَقُلْتُ حَدِيثًا حُدِّثْتُهُ عَنْكَ حِينَ اسْتَخْلَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلِيًّا ‏ ‏عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ فَغَضِبَ فَقَالَ مَنْ حَدَّثَكَ بِهِ فَكَرِهْتُ أَنْ أُخْبِرَهُ أَنَّ ابْنَهُ حَدَّثَنِيهِ فَيَغْضَبَ عَلَيْهِ ثُمَّ قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ خَرَجَ فِي ‏ ‏غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏اسْتَخْلَفَ ‏ ‏عَلِيًّا ‏ ‏عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏يَا رَسُولَ اللَّهِ مَا كُنْتُ أُحِبُّ أَنْ تَخْرُجَ وَجْهًا إِلَّا وَأَنَا مَعَكَ فَقَالَ ‏ ‏أَوَمَا ‏ ‏تَرْضَى أَنْ تَكُونَ مِنِّي بِمَنْزِلَةِ ‏ ‏هَارُونَ ‏ ‏مِنْ ‏ ‏مُوسَى ‏ ‏غَيْرَ أَنَّهُ لَا نَبِيَّ بَعْدِي ‏","","",""],[1451,1451,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ يَعْنِي ابْنَ أَنَسٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ ‏ ‏مَا سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ لِحَيٍّ يَمْشِي إِنَّهُ فِي الْجَنَّةِ إِلَّا ‏ ‏لِعَبْدِ اللَّهِ بْنِ سَلَامٍ ‏","","",""],[1452,1452,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏حَدَّثَنِي ‏ ‏مَخْرَمَةُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعْدًا ‏ ‏وَنَاسًا مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُونَ ‏ ‏كَانَ رَجُلَانِ أَخَوَانِ فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ أَحَدُهُمَا أَفْضَلَ مِنْ الْآخَرِ فَتُوُفِّيَ الَّذِي هُوَ أَفْضَلُهُمَا ثُمَّ عُمِّرَ الْآخَرُ بَعْدَهُ أَرْبَعِينَ لَيْلَةً ثُمَّ تُوُفِّيَ فَذُكِرَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَضْلُ الْأَوَّلِ عَلَى الْآخَرِ فَقَالَ أَلَمْ يَكُنْ ‏ ‏يُصَلِّي فَقَالُوا بَلَى يَا رَسُولَ اللَّهِ فَكَانَ لَا بَأْسَ بِهِ فَقَالَ مَا ‏ ‏يُدْرِيكُمْ مَاذَا بَلَغَتْ بِهِ صَلَاتُهُ ثُمَّ قَالَ عِنْدَ ذَلِكَ إِنَّمَا ‏ ‏مَثَلُ الصَّلَوَاتِ كَمَثَلِ نَهَرٍ جَارٍ بِبَابِ رَجُلٍ ‏ ‏غَمْرٍ ‏ ‏عَذْبٍ يَقْتَحِمُ فِيهِ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ فَمَا تُرَوْنَ ‏ ‏يُبْقِي ذَلِكَ مِنْ ‏ ‏دَرَنِهِ ‏","","",""],[1453,1453,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَأَنْ يَمْتَلِئَ جَوْفُ أَحَدِكُمْ قَيْحًا وَدَمًا خَيْرٌ لَهُ مِنْ أَنْ يَمْتَلِئَ شِعْرًا ‏","","",""],[1454,1454,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَدِمْتُ ‏ ‏الْمَدِينَةَ ‏ ‏فَبَلَغَنَا أَنَّ الطَّاعُونَ وَقَعَ ‏ ‏بِالْكُوفَةِ ‏ ‏قَالَ فَقُلْتُ مَنْ يَرْوِي هَذَا الْحَدِيثَ فَقِيلَ ‏ ‏عَامِرُ بْنُ سَعْدٍ ‏ ‏قَالَ وَكَانَ غَائِبًا ‏ ‏فَلَقِيتُ ‏ ‏إِبْرَاهِيمَ بْنَ سَعْدٍ ‏ ‏فَحَدَّثَنِي أَنَّهُ سَمِعَ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏يُحَدِّثُ ‏ ‏سَعْدًا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَقَعَ الطَّاعُونُ بِأَرْضٍ فَلَا تَدْخُلُوهَا وَإِذَا وَقَعَ وَأَنْتُمْ بِهَا فَلَا تَخْرُجُوا مِنْهَا ‏ ‏قَالَ ‏ ‏قُلْتُ أَنْتَ سَمِعْتَ ‏ ‏أُسَامَةَ ‏ ‏قَالَ ‏ ‏نَعَمْ ‏","","",""],[1455,1455,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قِتَالُ الْمُسْلِمِ كُفْرٌ وَسِبَابُهُ فِسْقٌ ‏","","",""],[1456,1456,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ قَدْ ‏ ‏شَفَانِي اللَّهُ مِنْ الْمُشْرِكِينَ فَهَبْ لِي هَذَا السَّيْفُ قَالَ إِنَّ هَذَا السَّيْفَ لَيْسَ لَكَ وَلَا لِي ضَعْهُ قَالَ فَوَضَعْتُهُ ثُمَّ رَجَعْتُ قُلْتُ عَسَى أَنْ يُعْطَى هَذَا السَّيْفُ الْيَوْمَ مَنْ لَمْ يُبْلِ بَلَائِي قَالَ إِذَا رَجُلٌ يَدْعُونِي مِنْ وَرَائِي قَالَ قُلْتُ قَدْ أُنْزِلَ فِيَّ شَيْءٌ قَالَ كُنْتَ سَأَلْتَنِي السَّيْفَ وَلَيْسَ هُوَ لِي وَإِنَّهُ قَدْ وُهِبَ لِي فَهُوَ لَكَ قَالَ وَأُنْزِلَتْ هَذِهِ الْآيَةُ ‏ { ‏يَسْأَلُونَكَ عَنْ ‏ ‏الْأَنْفَالِ ‏ ‏قُلْ ‏ ‏الْأَنْفَالُ ‏ ‏لِلَّهِ وَالرَّسُولِ ‏}","","",""],[1457,1457,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ هَذَا الْحَدِيثَ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْمُتَعَالِ بْنُ عَبْدِ الْوَهَّابِ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَحَدَّثَنَا ‏ ‏سَعِيدُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏الْمُجَالِدُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏جَاءَتْهُ ‏ ‏جُهَيْنَةُ ‏ ‏فَقَالُوا إِنَّكَ قَدْ نَزَلْتَ بَيْنَ أَظْهُرِنَا فَأَوْثِقْ لَنَا حَتَّى نَأْتِيَكَ وَتُؤْمِنَّا فَأَوْثَقَ لَهُمْ فَأَسْلَمُوا قَالَ فَبَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي رَجَبٍ وَلَا نَكُونُ مِائَةً وَأَمَرَنَا أَنْ ‏ ‏نُغِيرَ ‏ ‏عَلَى حَيٍّ مِنْ ‏ ‏بَنِي كِنَانَةَ ‏ ‏إِلَى جَنْبِ ‏ ‏جُهَيْنَةَ ‏ ‏فَأَغَرْنَا ‏ ‏عَلَيْهِمْ وَكَانُوا كَثِيرًا فَلَجَأْنَا إِلَى ‏ ‏جُهَيْنَةَ ‏ ‏فَمَنَعُونَا وَقَالُوا لِمَ تُقَاتِلُونَ فِي الشَّهْرِ الْحَرَامِ فَقُلْنَا إِنَّمَا نُقَاتِلُ مَنْ أَخْرَجَنَا مِنْ الْبَلَدِ الْحَرَامِ فِي الشَّهْرِ الْحَرَامِ فَقَالَ بَعْضُنَا لِبَعْضٍ مَا تَرَوْنَ فَقَالَ بَعْضُنَا ‏ ‏نَأْتِي نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنُخْبِرُهُ وَقَالَ قَوْمٌ لَا بَلْ نُقِيمُ هَاهُنَا وَقُلْتُ أَنَا فِي أُنَاسٍ مَعِي لَا بَلْ ‏ ‏نَأْتِي عِيرَ ‏ ‏قُرَيْشٍ ‏ ‏فَنَقْتَطِعُهَا فَانْطَلَقْنَا إِلَى الْعِيرِ وَكَانَ ‏ ‏الْفَيْءُ ‏ ‏إِذْ ذَاكَ مَنْ أَخَذَ شَيْئًا فَهُوَ لَهُ فَانْطَلَقْنَا إِلَى الْعِيرِ وَانْطَلَقَ أَصْحَابُنَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرُوهُ الْخَبَرَ فَقَامَ غَضْبَانًا مُحْمَرَّ الْوَجْهِ فَقَالَ أَذَهَبْتُمْ مِنْ عِنْدِي جَمِيعًا وَجِئْتُمْ مُتَفَرِّقِينَ ‏ ‏إِنَّمَا أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ الْفُرْقَةُ لَأَبْعَثَنَّ عَلَيْكُمْ رَجُلًا لَيْسَ بِخَيْرِكُمْ أَصْبَرُكُمْ عَلَى الْجُوعِ وَالْعَطَشِ فَبَعَثَ عَلَيْنَا ‏ ‏عَبْدَ اللَّهِ بْنَ جَحْشٍ الْأَسَدِيَّ ‏ ‏فَكَانَ أَوَّلَ أَمِيرٍ أُمِّرَ فِي الْإِسْلَامِ ‏","","",""],[1458,1458,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏وَعَنْ ‏ ‏نَافِعِ بْنِ عُتْبَةَ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُقَاتِلُونَ ‏ ‏جَزِيرَةَ الْعَرَبِ ‏ ‏فَيَفْتَحُهَا اللَّهُ لَكُمْ ثُمَّ تُقَاتِلُونَ ‏ ‏فَارِسَ ‏ ‏فَيَفْتَحُهَا اللَّهُ لَكُمْ ثُمَّ تُقَاتِلُونَ ‏ ‏الرُّومَ ‏ ‏فَيَفْتَحُهَا اللَّهُ لَكُمْ ثُمَّ تُقَاتِلُونَ ‏ ‏الدَّجَّالَ ‏ ‏فَيَفْتَحُهُ اللَّهُ لَكُمْ ‏ ‏قَالَ فَقَالَ ‏ ‏جَابِرٌ ‏ ‏لَا يَخْرُجُ ‏ ‏الدَّجَّالُ ‏ ‏حَتَّى يُفْتَتَحَ ‏ ‏الرُّومُ ‏","","",""],[1459,1459,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ عُتْبَةَ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَغْزُونَ ‏ ‏جَزِيرَةَ الْعَرَبِ ‏ ‏فَيَفْتَحُ اللَّهُ لَكُمْ وَتَغْزُونَ ‏ ‏فَارِسَ ‏ ‏فَيَفْتَحُهَا اللَّهُ لَكُمْ وَتَغْزُونَ ‏ ‏الرُّومَ ‏ ‏فَيَفْتَحُهَا اللَّهُ لَكُمْ وَتَغْزُونَ ‏ ‏الدَّجَّالَ ‏ ‏فَيَفْتَحُ اللَّهُ لَكُمْ ‏","","",""],[1460,1460,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مُحَمَّدِ بْنِ عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ابْنِ لَبِيبَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَنَّ أَصْحَابَ الْمَزَارِعِ فِي زَمَانِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانُوا ‏ ‏يُكْرُونَ ‏ ‏مَزَارِعَهُمْ بِمَا يَكُونُ عَلَى السَّوَاقِي مِنْ الزُّرُوعِ وَمَا سَعِدَ بِالْمَاءِ مِمَّا حَوْلَ النَّبْتِ فَجَاءُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاخْتَصَمُوا فِي بَعْضِ ذَلِكَ فَنَهَاهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُكْرُوا ‏ ‏بِذَلِكَ وَقَالَ ‏ ‏أَكْرُوا ‏ ‏بِالذَّهَبِ وَالْفِضَّةِ ‏","","",""],[1461,1461,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏وَيَعْقُوُبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ بْنِ أَبِي عَتِيقٍ ‏ ‏قَالَ ‏ ‏يَعْقُوبُ ‏ ‏ابْنُ أَبِي عَتِيقٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏سَعْدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا ‏ ‏تَنَخَّمَ ‏ ‏أَحَدُكُمْ فِي الْمَسْجِدِ فَلْيُغَيِّبْ نُخَامَتَهُ أَنْ تُصِيبَ جِلْدَ مُؤْمِنٍ أَوْ ثَوْبَهُ فَتُؤْذِيَهُ ‏","","",""],[1462,1462,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عَيَّاشٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏سَعْدٌ ‏ ‏عَنْ الْبَيْضَاءِ ‏ ‏بِالسُّلْتِ ‏ ‏فَكَرِهَهُ وَقَالَ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسْأَلُ عَنْ الرُّطَبِ بِالتَّمْرِ فَقَالَ يَنْقُصُ إِذَا يَبِسَ قَالُوا نَعَمْ قَالَ فَلَا إِذَنْ ‏","","",""],[1463,1463,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏بَلَغَ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْظَمُ الْمُسْلِمِينَ فِي الْمُسْلِمِينَ جُرْمًا مَنْ سَأَلَ عَنْ أَمْرٍ لَمْ يُحَرَّمْ فَحُرِّمَ عَلَى النَّاسِ مِنْ أَجْلِ مَسْأَلَتِهِ ‏","","",""],[1464,1464,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏مَرِضْتُ ‏ ‏بِمَكَّةَ ‏ ‏عَامَ الْفَتْحِ مَرَضًا شَدِيدًا ‏ ‏أَشْفَيْتُ ‏ ‏مِنْهُ عَلَى الْمَوْتِ فَأَتَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعُودُنِي قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ لِي مَالًا كَثِيرًا وَلَيْسَ يَرِثُنِي إِلَّا ابْنَتِي أَفَأَتَصَدَّقُ بِثُلُثَيْ مَالِي ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً أَتَصَدَّقُ بِمَالِي ‏ ‏قَالَ لَا قَالَ فَأَتَصَدَّقُ بِثُلُثَيْ مَالِي قَالَ لَا قُلْتُ ‏ ‏فَالشَّطْرُ ‏ ‏قَالَ لَا قَالَ قُلْتُ الثُّلُثُ قَالَ ‏ ‏الثُّلُثُ وَالثُّلُثُ كَبِيرٌ إِنَّكَ أَنْ تَتْرُكَ وَرَثَتَكَ أَغْنِيَاءَ خَيْرٌ مِنْ أَنْ تَتْرُكَهُمْ عَالَةً ‏ ‏يَتَكَفَّفُونَ ‏ ‏النَّاسَ إِنَّكَ لَنْ تُنْفِقَ نَفَقَةً إِلَّا أُجِرْتَ فِيهَا حَتَّى اللُّقْمَةَ تَرْفَعُهَا إِلَى ‏ ‏فِي ‏ ‏امْرَأَتِكَ قُلْتُ يَا رَسُولَ اللَّهِ أُخَلَّفُ عَنْ هِجْرَتِي قَالَ إِنَّكَ لَنْ تُخَلَّفَ بَعْدِي فَتَعْمَلَ عَمَلًا تُرِيدُ بِهِ وَجْهَ اللَّهِ إِلَّا ازْدَدْتَ بِهِ رِفْعَةً وَدَرَجَةً وَلَعَلَّكَ أَنْ تُخَلَّفَ حَتَّى يَنْتَفِعَ بِكَ أَقْوَامٌ وَيُضَرَّ بِكَ آخَرُونَ اللَّهُمَّ أَمْضِ لِأَصْحَابِي هِجْرَتَهُمْ وَلَا تَرُدَّهُمْ عَلَى ‏ ‏أَعْقَابِهِمْ ‏ ‏لَكِنْ ‏ ‏الْبَائِسُ ‏ ‏سَعْدُ ابْنُ خَوْلَةَ ‏ ‏يَرْثِي ‏ ‏لَهُ أَنْ مَاتَ ‏ ‏بِمَكَّةَ ‏","","",""],[1465,1465,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَلِيٍّ ‏ ‏أَنْتَ مِنِّي بِمَنْزِلَةِ ‏ ‏هَارُونَ ‏ ‏مِنْ ‏ ‏مُوسَى ‏ ‏قِيلَ ‏ ‏لِسُفْيَانَ ‏ ‏غَيْرَ أَنَّهُ لَا نَبِيَّ بَعْدِي قَالَ قَالَ نَعَمْ ‏","","",""],[1466,1466,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏سَمِعَهُ مِنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏شَكَا أَهْلُ ‏ ‏الْكُوفَةِ ‏ ‏سَعْدًا ‏ ‏إِلَى ‏ ‏عُمَرَ ‏ ‏فَقَالُوا إِنَّهُ لَا يُحْسِنُ ‏ ‏يُصَلِّي قَالَ ‏ ‏آلْأَعَارِيبُ وَاللَّهِ ‏ ‏مَا ‏ ‏آلُو ‏ ‏بِهِمْ عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الظُّهْرِ وَالْعَصْرِ ‏ ‏أَرْكُدُ ‏ ‏فِي الْأُولَيَيْنِ ‏ ‏وَأَحْذِفُ ‏ ‏فِي الْأُخْرَيَيْنِ فَسَمِعْتُ ‏ ‏عُمَرَ ‏ ‏يَقُولُ كَذَلِكَ الظَّنُّ بِكَ يَا ‏ ‏أَبَا إِسْحَاقَ ‏","","",""],[1467,1467,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏سَمِعْتُ ‏ ‏ابْنَ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي نَهِيكٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ مِنَّا مَنْ لَمْ ‏ ‏يَتَغَنَّ ‏ ‏بِالْقُرْآنِ ‏","","",""],[1468,1468,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَوْسٍ ‏ ‏سَمِعْتُ ‏ ‏عُمَرَ ‏ ‏يَقُولُ ‏ ‏لِعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏وَطَلْحَةَ ‏ ‏وَالزُّبَيْرِ ‏ ‏وَسَعْدٍ ‏ ‏نَشَدْتُكُمْ اللَّهَ الَّذِي تَقُومُ بِهِ السَّمَاءُ وَالْأَرْضُ ‏ ‏وَقَالَ ‏ ‏مَرَّةً الَّذِي بِإِذْنِهِ تَقُومُ ‏ ‏أَعَلِمْتُمْ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّا ‏ ‏لَا نُورَثُ مَا تَرَكْنَا ‏ ‏صَدَقَةٌ ‏ ‏قَالُوا اللَّهُمَّ نَعَمْ ‏","","",""],[1469,1469,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ يَعْنِي ابْنَ أَبِي الْعَبَّاسِ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ قِرْوَاشٍ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏قِيلَ ‏ ‏لِسُفْيَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏ ‏قَالَ ‏ ‏شَيْطَانُ ‏ ‏الرَّدْهَةِ ‏ ‏يَحْتَدِرُهُ ‏ ‏يَعْنِي رَجُلًا مِنْ ‏ ‏بَجِيلَةَ ‏","","",""],[1470,1470,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي عَيَّاشٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏سَعْدٌ ‏ ‏عَنْ بَيْعِ ‏ ‏سُلْتٍ ‏ ‏بِشَعِيرٍ أَوْ شَيْءٍ مِنْ هَذَا فَقَالَ سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ تَمْرٍ بِرُطَبٍ فَقَالَ ‏ ‏تَنْقُصُ الرَّطْبَةُ إِذَا يَبِسَتْ قَالُوا نَعَمْ قَالَ فَلَا إِذَنْ ‏","","",""],[1471,1471,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعْدًا ‏ ‏يَقُولُ ‏ ‏سَمِعَتْ أُذُنَايَ وَوَعَى قَلْبِي مِنْ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏مَنْ ادَّعَى إِلَى غَيْرِ أَبِيهِ وَهُوَ يَعْلَمُ أَنَّهُ غَيْرُ أَبِيهِ فَالْجَنَّةُ عَلَيْهِ حَرَامٌ ‏ ‏قَالَ ‏ ‏فَلَقِيتُ ‏ ‏أَبَا بَكْرَةَ ‏ ‏فَحَدَّثْتُهُ ‏ ‏فَقَالَ ‏ ‏وَأَنَا سَمِعَهُ ‏ ‏أُذُنَايَ وَوَعَى قَلْبِي مِنْ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1472,1472,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏الْحَضْرَمِيِّ بْنِ لَاحِقٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏الطِّيَرَةِ ‏ ‏فَانْتَهَرَنِي وَقَالَ مَنْ حَدَّثَكَ فَكَرِهْتُ أَنْ أُحَدِّثَهُ مَنْ حَدَّثَنِي قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا عَدْوَى وَلَا ‏ ‏طِيَرَةَ ‏ ‏وَلَا ‏ ‏هَامَ ‏ ‏إِنْ تَكُنِ ‏ ‏الطِّيَرَةُ ‏ ‏فِي شَيْءٍ فَفِي الْفَرَسِ وَالْمَرْأَةِ وَالدَّارِ وَإِذَا سَمِعْتُمْ بِالطَّاعُونِ بِأَرْضٍ فَلَا تَهْبِطُوا وَإِذَا كَانَ بِأَرْضٍ وَأَنْتُمْ بِهَا فَلَا تَفِرُّوا مِنْهُ ‏","","",""],[1473,1473,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ إِبْرَاهِيمَ ‏ ‏أَنْبَأَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏قَالَ قَالَ ‏ ‏سَعْدٌ ‏ ‏يَا رَسُولَ اللَّهِ أَيُّ النَّاسِ أَشَدُّ بَلَاءً قَالَ ‏ ‏الْأَنْبِيَاءُ ثُمَّ الْأَمْثَلُ فَالْأَمْثَلُ حَتَّى ‏ ‏يُبْتَلَى الْعَبْدُ عَلَى قَدْرِ دِينِهِ ذَاكَ فَإِنْ كَانَ صُلْبَ الدِّينِ ابْتُلِيَ عَلَى قَدْرِ ذَاكَ ‏ ‏وَقَالَ مَرَّةً أَشَدُّ بَلَاءً ‏ ‏وَإِنْ كَانَ فِي دِينِهِ رِقَّةٌ ابْتُلِيَ عَلَى قَدْرِ ذَاكَ ‏ ‏وَقَالَ مَرَّةً عَلَى حَسَبِ دِينِهِ ‏ ‏قَالَ فَمَا ‏ ‏تَبْرَحُ ‏ ‏الْبَلَايَا عَنْ الْعَبْدِ حَتَّى يَمْشِيَ فِي الْأَرْضِ ‏ ‏يَعْنِي وَمَا إِنْ عَلَيْهِ مِنْ خَطِيئَةٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَقَالَ مَرَّةً ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏","","",""],[1474,1474,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عُبَيْدِ اللَّهِ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏بَدْرٍ ‏ ‏قُتِلَ أَخِي ‏ ‏عُمَيْرٌ ‏ ‏وَقَتَلْتُ ‏ ‏سَعِيدَ بْنَ الْعَاصِ ‏ ‏وَأَخَذْتُ سَيْفَهُ وَكَانَ يُسَمَّى ذَا الْكَتِيفَةِ فَأَتَيْتُ بِهِ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اذْهَبْ فَاطْرَحْهُ فِي ‏ ‏الْقَبَضِ ‏ ‏قَالَ فَرَجَعْتُ وَبِي مَا لَا يَعْلَمُهُ إِلَّا اللَّهُ مِنْ قَتْلِ أَخِي وَأَخْذِ سَلَبِي قَالَ فَمَا جَاوَزْتُ إِلَّا يَسِيرًا حَتَّى ‏ ‏نَزَلَتْ سُورَةُ ‏ ‏الْأَنْفَالِ ‏ ‏فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اذْهَبْ فَخُذْ سَيْفَكَ ‏","","",""],[1475,1475,"","","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ عَبْدِ الْحَمِيدِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏قَالَ ‏ ‏شَكَا أَهْلُ ‏ ‏الْكُوفَةِ ‏ ‏سَعْدًا ‏ ‏إِلَى ‏ ‏عُمَرَ ‏ ‏فَقَالُوا لَا يُحْسِنُ ‏ ‏يُصَلِّي فَذَكَرَ ذَلِكَ ‏ ‏عُمَرُ ‏ ‏لَهُ فَقَالَ ‏ ‏أَمَّا صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَدْ كُنْتُ أُصَلِّي بِهِمْ ‏ ‏أَرْكُدُ ‏ ‏فِي الْأُولَيَيْنِ ‏ ‏وَأَحْذِفُ ‏ ‏فِي الْأُخْرَيَيْنِ فَقَالَ ذَاكَ الظَّنُّ بِكَ يَا ‏ ‏أَبَا إِسْحَاقَ ‏","","",""],[1476,1476,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ نُبَيْهٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَبْدِ اللَّهِ الْقَرَّاظُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعْدَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَرَادَ أَهْلَ ‏ ‏الْمَدِينَةِ ‏ ‏بِدَهْمٍ ‏ ‏أَوْ بِسُوءٍ ‏ ‏أَذَابَهُ اللَّهُ كَمَا يَذُوبُ الْمِلْحُ فِي الْمَاءِ ‏","","",""],[1477,1477,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ ابْنِ لَبِيبَةَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ الذِّكْرِ الْخَفِيُّ وَخَيْرُ الرِّزْقِ مَا يَكْفِي ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَمْرِو بْنِ عُثْمَانَ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ عَبْدِ الرَّحْمَنِ ابْنِ لَبِيبَةَ ‏ ‏أَخْبَرَهُ ‏ ‏فَذَكَرَهُ ‏","","",""],[1478,1478,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُوسَى الْجُهَنِيِّ ‏ ‏حَدَّثَنِي ‏ ‏مُصْعَبُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ أَعْرَابِيًّا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ عَلِّمْنِي كَلَامًا أَقُولُهُ قَالَ قُلْ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ اللَّهُ أَكْبَرُ كَبِيرًا وَالْحَمْدُ لِلَّهِ كَثِيرًا وَسُبْحَانَ اللَّهِ رَبِّ الْعَالَمِينَ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَزِيزِ الْحَكِيمِ خَمْسًا قَالَ هَؤُلَاءِ لِرَبِّي فَمَا لِي قَالَ قُلْ اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَارْزُقْنِي وَاهْدِنِي وَعَافِنِي ‏","","",""],[1479,1479,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ الْأَنْصَارِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏سَعْدًا ‏ ‏يَقُولُ ‏ ‏جَمَعَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَوَيْهِ يَوْمَ ‏ ‏أُحُدٍ ‏","","",""],[1480,1480,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُوسَى يَعْنِي الْجُهَنِيَّ ‏ ‏حَدَّثَنِي ‏ ‏مُصْعَبُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَيَعْجِزُ أَحَدُكُمْ أَنْ يَكْسِبَ كُلَّ يَوْمٍ أَلْفَ حَسَنَةٍ فَقَالَ رَجُلٌ مِنْ جُلَسَائِهِ كَيْفَ يَكْسِبُ أَحَدُنَا أَلْفَ حَسَنَةٍ قَالَ ‏ ‏يُسَبِّحُ مِائَةَ تَسْبِيحَةٍ تُكْتَبُ لَهُ أَلْفُ حَسَنَةٍ أَوْ يُحَطُّ عَنْهُ أَلْفُ خَطِيئَةٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَيْضًا ‏ ‏أَوْ يُحَطُّ ‏ ‏وَيَعْلَى ‏ ‏أَيْضًا ‏ ‏أَوْ يُحَطُّ ‏","","",""],[1481,1481,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنِي ‏ ‏مُصْعَبُ بْنُ ثَابِتٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏سَعْدِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ حَتَّى يُرَى بَيَاضُ خَدَّيْهِ ‏","","",""],[1482,1482,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنِ ‏ ‏الْحُكَيْمِ بْنِ عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏سَعْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَالَ حِينَ يَسْمَعُ الْمُؤَذِّنَ وَأَنَا أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ رَضِينَا بِاللَّهِ رَبًّا ‏ ‏وَبِمُحَمَّدٍ ‏ ‏رَسُولًا وَبِالْإِسْلَامِ دِينًا غُفِرَ لَهُ ذَنْبُهُ ‏ ‏حَدَّثَنَاه ‏ ‏قُتَيْبَةُ ‏ ‏عَنِ ‏ ‏لَيْثٍ ‏ ‏عَنِ ‏ ‏الْحُكَيْمِ بْنِ عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏","","",""],[1483,1483,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعْدَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏إِنِّي لَأَوَّلُ ‏ ‏الْعَرَبِ ‏ ‏رَمَى بِسَهْمٍ فِي سَبِيلِ اللَّهِ وَلَقَدْ ‏ ‏أَتَيْنَا نَغْزُو مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا لَنَا طَعَامٌ نَأْكُلُهُ إِلَّا ‏ ‏وَرَقَ الْحُبْلَةِ ‏ ‏وَهَذَا ‏ ‏السَّمُرَ ‏ ‏حَتَّى إِنَّ أَحَدَنَا لَيَضَعُ كَمَا تَضَعُ الشَّاةُ مَا لَهُ خِلْطٌ ثُمَّ أَصْبَحَتْ ‏ ‏بَنُو أَسَدٍ ‏ ‏يُعَزِّرُونِي ‏ ‏عَلَى الدِّينِ لَقَدْ خِبْتُ إِذَنْ وَضَلَّ عَمَلِي ‏","","",""],[1484,1484,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏أُنْزِلَتْ فِي أَبِي أَرْبَعُ آيَاتٍ قَالَ قَالَ ‏ ‏أَبِي ‏ ‏أَصَبْتُ سَيْفًا قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏نَفِّلْنِيهِ ‏ ‏قَالَ ضَعْهُ قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏نَفِّلْنِيهِ ‏ ‏أُجْعَلْ كَمَنْ لَا ‏ ‏غَنَاءَ ‏ ‏لَهُ قَالَ ضَعْهُ مِنْ حَيْثُ أَخَذْتَهُ فَنَزَلَتْ ‏ ‏يَسْأَلُونَكَ ‏ ‏الْأَنْفَالَ ‏ ‏قَالَ وَهِيَ فِي قِرَاءَةِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏كَذَلِكَ ‏ { ‏قُلْ ‏ ‏الْأَنْفَالُ ‏ } ‏وَقَالَتْ أُمِّي أَلَيْسَ اللَّهُ يَأْمُرُكَ بِصِلَةِ الرَّحِمِ وَبِرِّ الْوَالِدَيْنِ وَاللَّهِ لَا آكُلُ طَعَامًا وَلَا أَشْرَبُ شَرَابًا حَتَّى تَكْفُرَ ‏ ‏بِمُحَمَّدٍ ‏ ‏فَكَانَتْ لَا تَأْكُلُ حَتَّى ‏ ‏يَشْجُرُوا ‏ ‏فَمَهَا بِعَصًا فَيَصُبُّوا فِيهِ الشَّرَابَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأُرَاهُ قَالَ وَالطَّعَامَ ‏ ‏فَأُنْزِلَتْ ‏ { ‏وَوَصَّيْنَا الْإِنْسَانَ بِوَالِدَيْهِ حَمَلَتْهُ أُمُّهُ وَهْنًا عَلَى ‏ ‏وَهْنٍ ‏ ‏وَقَرَأَ حَتَّى بَلَغَ ‏ ‏بِمَا كُنْتُمْ تَعْمَلُونَ ‏} ‏وَدَخَلَ عَلَيَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا مَرِيضٌ قُلْتُ يَا رَسُولَ اللَّهِ أُوصِي بِمَالِي كُلِّهِ فَنَهَانِي قُلْتُ النِّصْفُ قَالَ لَا قُلْتُ الثُّلُثُ فَسَكَتَ فَأَخَذَ النَّاسُ بِهِ وَصَنَعَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏طَعَامًا فَأَكَلُوا وَشَرِبُوا ‏ ‏وَانْتَشَوْا ‏ ‏مِنْ الْخَمْرِ وَذَاكَ قَبْلَ أَنْ تُحَرَّمَ فَاجْتَمَعْنَا عِنْدَهُ فَتَفَاخَرُوا وَقَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏الْأَنْصَارُ ‏ ‏خَيْرٌ وَقَالَتْ ‏ ‏الْمُهَاجِرُونَ ‏ ‏الْمُهَاجِرُونَ ‏ ‏خَيْرٌ ‏ ‏فَأَهْوَى ‏ ‏لَهُ ‏ ‏رَجُلٌ ‏ ‏بِلَحْيَيْ ‏ ‏جَزُورٍ ‏ ‏فَفَزَرَ أَنْفَهُ فَكَانَ أَنْفُ ‏ ‏سَعْدٍ ‏ ‏مَفْزُورًا فَنَزَلَتْ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ ‏ ‏إِلَى قَوْلِهِ ‏ ‏فَهَلْ أَنْتُمْ مُنْتَهُونَ ‏}","","",""],[1485,1485,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏أَنْبَأَنَا ‏ ‏سُلَيْمَانُ يَعْنِي التَّيْمِيَّ ‏ ‏حَدَّثَنِي ‏ ‏غُنَيْمٌ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏الْمُتْعَةِ ‏ ‏قَالَ فَعَلْنَاهَا وَهَذَا كَافِرٌ بِالْعُرُشِ ‏ ‏يَعْنِي ‏ ‏مُعَاوِيَةَ ‏","","",""],[1486,1486,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَنْ يَمْتَلِئَ جَوْفُ الرَّجُلِ قَيْحًا خَيْرٌ مِنْ أَنْ يَمْتَلِئَ شِعْرًا ‏","","",""],[1487,1487,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ بْنِ عَدِيٍّ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ ‏ ‏سَعْدٍ ‏ ‏فَقُلْتُ بِيَدَيَّ هَكَذَا ‏ ‏وَوَصَفَ ‏ ‏يَحْيَى ‏ ‏التَّطْبِيقَ فَضَرَبَ بِيَدَيَّ ‏ ‏وَقَالَ ‏ ‏كُنَّا نَفْعَلُ هَذَا فَأُمِرْنَا أَنْ نَرْفَعَ إِلَى الرُّكَبِ ‏","","",""],[1488,1488,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏عَنْ ‏ ‏عَائِشَةَ بِنْتِ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَصَبَّحَ بِسَبْعِ تَمَرَاتٍ مِنْ عَجْوَةٍ لَمْ يَضُرَّهُ ذَلِكَ الْيَوْمَ سُمٌّ وَلَا سِحْرٌ ‏ ‏حَدَّثَنَا ‏ ‏مَكِّيٌّ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏مِثْلَهُ ‏ ‏حَدَّثَنَاه ‏ ‏أَبُو بَدْرٍ ‏ ‏عَنْ ‏ ‏هَاشِمٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏","","",""],[1489,1489,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ يَعْنِي ابْنَ حَكِيمٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَامِرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أُحَرِّمُ مَا بَيْنَ لَابَتَيْ ‏ ‏الْمَدِينَةِ ‏ ‏أَنْ يُقْطَعَ ‏ ‏عِضَاهُهَا ‏ ‏أَوْ يُقْتَلَ صَيْدُهَا وَقَالَ ‏ ‏الْمَدِينَةُ ‏ ‏خَيْرٌ لَهُمْ لَوْ كَانُوا يَعْلَمُونَ لَا يَخْرُجُ مِنْهَا أَحَدٌ رَغْبَةً عَنْهَا إِلَّا أَبْدَلَ اللَّهُ فِيهَا مَنْ هُوَ خَيْرٌ مِنْهُ وَلَا يَثْبُتُ أَحَدٌ عَلَى ‏ ‏لَأْوَائِهَا ‏ ‏وَجَهْدِهَا إِلَّا كُنْتُ لَهُ شَهِيدًا ‏ ‏أَوْ شَفِيعًا ‏ ‏يَوْمَ الْقِيَامَةِ ‏","","",""],[1490,1490,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَامِرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقْبَلَ ذَاتَ يَوْمٍ مِنْ ‏ ‏الْعَالِيَةِ ‏ ‏حَتَّى إِذَا مَرَّ بِمَسْجِدِ ‏ ‏بَنِي مُعَاوِيَةَ ‏ ‏دَخَلَ فَرَكَعَ فِيهِ رَكْعَتَيْنِ وَصَلَّيْنَا مَعَهُ وَدَعَا رَبَّهُ طَوِيلًا ثُمَّ انْصَرَفَ إِلَيْنَا فَقَالَ سَأَلْتُ رَبِّي ثَلَاثًا فَأَعْطَانِي اثْنَتَيْنِ وَمَنَعَنِي وَاحِدَةً ‏ ‏سَأَلْتُ رَبِّي أَنْ لَا يُهْلِكَ أُمَّتِي بِسَنَةٍ فَأَعْطَانِيهَا وَسَأَلْتُهُ أَنْ لَا يُهْلِكَ أُمَّتِي بِالْغَرَقِ فَأَعْطَانِيهَا وَسَأَلْتُهُ أَنْ لَا يَجْعَلَ ‏ ‏بَأْسَهُمْ ‏ ‏بَيْنَهُمْ فَمَنَعَنِيهَا ‏","","",""],[1491,1491,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْعَيْزَارِ بْنِ حُرَيْثٍ الْعَبْدِيِّ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَجِبْتُ لِلْمُؤْمِنِ إِنْ أَصَابَهُ خَيْرٌ حَمِدَ اللَّهَ وَشَكَرَ وَإِنْ أَصَابَتْهُ مُصِيبَةٌ ‏ ‏احْتَسَبَ ‏ ‏وَصَبَرَ الْمُؤْمِنُ يُؤْجَرُ فِي كُلِّ شَيْءٍ حَتَّى فِي اللُّقْمَةِ يَرْفَعُهَا إِلَى ‏ ‏فِيهِ ‏","","",""],[1492,1492,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي خَالِدٍ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ بْنِ عَدِيٍّ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏كُنْتُ إِذَا رَكَعْتُ وَضَعْتُ يَدَيَّ بَيْنَ رُكْبَتَيَّ قَالَ فَرَآنِي أَبِي ‏ ‏سَعْدُ بْنُ مَالِكٍ ‏ ‏فَنَهَانِي وَقَالَ إِنَّا كُنَّا نَفْعَلُهُ فَنُهِينَا عَنْهُ ‏","","",""],[1493,1493,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ مَالِكٍ ‏ ‏وَخُزَيْمَةَ بْنِ ثَابِتٍ ‏ ‏وَأُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالُوا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏هَذَا الطَّاعُونَ ‏ ‏رِجْزٌ ‏ ‏أَوْ بَقِيَّةٌ ‏ ‏مِنْ عَذَابٍ عُذِّبَ بِهِ قَوْمٌ قَبْلَكُمْ فَإِذَا وَقَعَ بِأَرْضٍ وَأَنْتُمْ بِهَا فَلَا تَخْرُجُوا مِنْهَا فِرَارًا مِنْهُ وَإِذَا سَمِعْتُمْ بِهِ فِي أَرْضٍ فَلَا تَدْخُلُوا عَلَيْهِ ‏","","",""],[1494,1494,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ عَامِرِ بْنِ سَعْدِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَصِفَنَّ ‏ ‏الدَّجَّالَ ‏ ‏صِفَةً لَمْ يَصِفْهَا مَنْ كَانَ قَبْلِي إِنَّهُ أَعْوَرُ وَاللَّهُ عَزَّ وَجَلَّ لَيْسَ بِأَعْوَرَ ‏","","",""],[1495,1495,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ أَتَاهُ ‏ ‏رَهْطٌ ‏ ‏فَسَأَلُوهُ فَأَعْطَاهُمْ إِلَّا رَجُلًا مِنْهُمْ قَالَ ‏ ‏سَعْدٌ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ أَعْطَيْتَهُمْ وَتَرَكْتَ فُلَانًا فَوَاللَّهِ إِنِّي لَأَرَاهُ مُؤْمِنًا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ مُسْلِمًا فَرَدَّ عَلَيْهِ ‏ ‏سَعْدٌ ‏ ‏ذَلِكَ ثَلَاثًا مُؤْمِنًا وَرَدَّ عَلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ مُسْلِمًا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الثَّالِثَةِ وَاللَّهِ ‏ ‏إِنِّي لَأُعْطِي الرَّجُلَ الْعَطَاءَ لَغَيْرُهُ أَحَبُّ إِلَيَّ مِنْهُ خَوْفًا أَنْ ‏ ‏يَكُبَّهُ ‏ ‏اللَّهُ عَلَى وَجْهِهِ فِي النَّارِ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏لَقِيتُ ‏ ‏سُفْيَانَ ‏ ‏بِمَكَّةَ ‏ ‏فَأَوَّلُ مَنْ سَأَلَنِي عَنْهُ قَالَ ‏ ‏كَيْفَ ‏ ‏شُجَاعٌ ‏ ‏يَعْنِي ‏ ‏أَبَا بَدْرٍ ‏","","",""],[1496,1496,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏وَهَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏صَالِحُ بْنُ كَيْسَانَ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعِنْدَهُ نِسْوَةٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏يَسْأَلْنَهُ وَيَسْتَكْثِرْنَ رَافِعَاتٍ أَصْوَاتَهُنَّ فَلَمَّا سَمِعْنَ صَوْتَ ‏ ‏عُمَرَ ‏ ‏انْقَمَعْنَ وَسَكَتْنَ فَضَحِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا عَدُوَّاتِ أَنْفُسِهِنَّ تَهَبْنَنِي وَلَا تَهَبْنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْنَ إِنَّكَ ‏ ‏أَفَظُّ ‏ ‏مِنْ رَسُولِ اللَّهِ وَأَغْلَظُ فَقَالَ رَسُولُ اللَّهِ يَا ‏ ‏عُمَرُ ‏ ‏مَا لَقِيَكَ الشَّيْطَانُ سَالِكًا ‏ ‏فَجًّا ‏ ‏إِلَّا سَلَكَ ‏ ‏فَجًّا ‏ ‏غَيْرَ ‏ ‏فَجِّكَ ‏","","",""],[1497,1497,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عِكْرِمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَبِيبَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُكْرِي ‏ ‏الْأَرْضَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَا عَلَى ‏ ‏السَّوَاقِي ‏ ‏مِنْ الزَّرْعِ وَبِمَا سَعِدَ بِالْمَاءِ مِنْهَا فَنَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ ‏ ‏وَأَذِنَ لَنَا أَوْ ‏ ‏رَخَّصَ بِأَنْ ‏ ‏نُكْرِيَهَا ‏ ‏بِالذَّهَبِ ‏ ‏وَالْوَرِقِ ‏","","",""],[1498,1498,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏خَلَّفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏فِي ‏ ‏غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏تُخَلِّفُنِي ‏ ‏فِي النِّسَاءِ وَالصِّبْيَانِ قَالَ ‏ ‏أَمَا ‏ ‏تَرْضَى أَنْ تَكُونَ مِنِّي بِمَنْزِلَةِ ‏ ‏هَارُونَ ‏ ‏مِنْ ‏ ‏مُوسَى ‏ ‏غَيْرَ أَنَّهُ لَا نَبِيَّ بَعْدِي ‏","","",""],[1499,1499,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏زِيَادُ بْنُ مِخْرَاقٍ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏قَيْسَ بْنَ عَبَايَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مَوْلًى لِسَعْدٍ ‏ ‏ح ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ مِخْرَاقٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَيْسَ بْنَ عَبَايَةَ الْقَيْسِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مَوْلًى لِسَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنِ ‏ ‏ابْنٍ لِسَعْدٍ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُصَلِّي فَكَانَ يَقُولُ فِي دُعَائِهِ اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَسْأَلُكَ مِنْ نَعِيمِهَا وَبَهْجَتِهَا وَمِنْ كَذَا وَمِنْ كَذَا وَمِنْ كَذَا وَمِنْ كَذَا وَأَعُوذُ بِكَ مِنْ النَّارِ وَسَلَاسِلِهَا وَأَغْلَالِهَا وَمِنْ كَذَا وَمِنْ كَذَا قَالَ فَسَكَتَ عَنْهُ ‏ ‏سَعْدٌ ‏ ‏فَلَمَّا صَلَّى قَالَ لَهُ ‏ ‏سَعْدٌ ‏ ‏تَعَوَّذْتَ مِنْ شَرٍّ عَظِيمٍ وَسَأَلْتَ نَعِيمًا عَظِيمًا ‏ ‏أَوْ قَالَ طَوِيلًا ‏ ‏شُعْبَةُ ‏ ‏شَكَّ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ ‏ ‏سَيَكُونُ قَوْمٌ يَعْتَدُونَ فِي الدُّعَاءِ وَقَرَأَ ‏ { ‏ادْعُوا رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً إِنَّهُ لَا يُحِبُّ الْمُعْتَدِينَ ‏} ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَا أَدْرِي قَوْلُهُ ‏ { ‏ادْعُوا رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً ‏} ‏هَذَا مِنْ قَوْلِ ‏ ‏سَعْدٍ ‏ ‏أَوْ قَوْلِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ لَهُ ‏ ‏سَعْدٌ ‏ ‏قُلْ اللَّهُمَّ أَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ وَأَعُوذُ بِكَ مِنْ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ ‏","","",""],[1500,1500,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏مُصْعَبٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَنَّهُ كَانَ يَأْمُرُ بِهَؤُلَاءِ الْخَمْسِ وَيُخْبِرُ بِهِنَّ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْبُخْلِ وَأَعُوذُ بِكَ مِنْ الْجُبْنِ وَأَعُوذُ بِكَ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ ‏","","",""],[1501,1501,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ كَيْسَانَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي سُفْيَانَ بْنِ الْعَلَاءِ بْنِ جَارِيَةَ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ الْحَكَمِ أَبِي الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَهَانَ ‏ ‏قُرَيْشًا ‏ ‏أَهَانَهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[1502,1502,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏مَرَّةً أُخْرَى ‏ ‏حَدَّثَنِي ‏ ‏صَالِحُ بْنُ كَيْسَانَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي سُفْيَانَ بْنِ الْعَلَاءِ بْنِ جَارِيَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏سَعْدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ يُرِدْ هَوَانَ ‏ ‏قُرَيْشٍ ‏ ‏أَهَانَهُ اللَّهُ ‏","","",""],[1503,1503,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏يَقُولُ ‏ ‏لَقَدْ ‏ ‏رَدَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏عُثْمَانَ بْنِ مَظْعُونٍ ‏ ‏التَّبَتُّلَ ‏ ‏وَلَوْ أَذِنَ لَهُ فِيهِ ‏ ‏لَاخْتَصَيْنَا ‏","","",""],[1504,1504,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثٍ ‏","","",""],[1505,1505,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏حَلَفْتُ ‏ ‏بِاللَّاتِ ‏ ‏وَالْعُزَّى ‏ ‏فَقَالَ أَصْحَابِي قَدْ قُلْتَ هُجْرًا فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ إِنَّ الْعَهْدَ كَانَ قَرِيبًا وَإِنِّي حَلَفْتُ ‏ ‏بِاللَّاتِ ‏ ‏وَالْعُزَّى ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ ثَلَاثًا ثُمَّ انْفُثْ عَنْ يَسَارِكَ ثَلَاثًا وَتَعَوَّذْ وَلَا تَعُدْ ‏","","",""],[1506,1506,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ مُؤَمَّلُ بْنُ إِسْمَاعِيلَ ‏ ‏وَعَفَّانُ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ ‏ ‏بِقَصْعَةٍ ‏ ‏مِنْ ‏ ‏ثَرِيدٍ ‏ ‏فَأَكَلَ فَفَضَلَ مِنْهُ فَضْلَةٌ فَقَالَ ‏ ‏يَدْخُلُ مِنْ هَذَا ‏ ‏الْفَجِّ ‏ ‏رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ يَأْكُلُ هَذِهِ الْفَضْلَةَ قَالَ ‏ ‏سَعْدٌ ‏ ‏وَقَدْ كُنْتُ تَرَكْتُ أَخِي ‏ ‏عُمَيْرَ بْنَ أَبِي وَقَّاصٍ ‏ ‏يَتَهَيَّأُ لِأَنْ يَأْتِيَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَطَمِعْتُ أَنْ يَكُونَ هُوَ فَجَاءَ ‏ ‏عَبْدُ اللَّهِ بْنُ سَلَامٍ ‏ ‏فَأَكَلَهَا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ فَمَرَرْتُ ‏ ‏بِعُوَيْمِرِ بْنِ مَالِكٍ ‏","","",""],[1507,1507,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ يَعْنِي ابْنَ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ الْقَرَّاظُ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏سَعْدَ بْنَ مَالِكٍ ‏ ‏وَأَبَا هُرَيْرَةَ ‏ ‏يَقُولَانِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ بَارِكْ لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏فِي ‏ ‏مَدِينَتِهِمْ ‏ ‏وَبَارِكْ لَهُمْ فِي ‏ ‏صَاعِهِمْ ‏ ‏وَبَارِكْ لَهُمْ فِي ‏ ‏مُدِّهِمْ ‏ ‏اللَّهُمَّ إِنَّ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَبْدُكَ وَخَلِيلُكَ وَإِنِّي عَبْدُكَ وَرَسُولُكَ وَإِنَّ ‏ ‏إِبْرَاهِيمَ ‏ ‏سَأَلَكَ لِأَهْلِ ‏ ‏مَكَّةَ ‏ ‏وَإِنِّي أَسْأَلُكَ لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏كَمَا سَأَلَكَ ‏ ‏إِبْرَاهِيمُ ‏ ‏لِأَهْلِ ‏ ‏مَكَّةَ ‏ ‏وَمِثْلَهُ مَعَهُ ‏ ‏إِنَّ ‏ ‏الْمَدِينَةَ ‏ ‏مُشَبَّكَةٌ بِالْمَلَائِكَةِ عَلَى كُلِّ ‏ ‏نَقْبٍ ‏ ‏مِنْهَا مَلَكَانِ يَحْرُسَانِهَا لَا يَدْخُلُهَا الطَّاعُونُ وَلَا ‏ ‏الدَّجَّالُ ‏ ‏مَنْ أَرَادَهَا بِسُوءٍ أَذَابَهُ اللَّهُ كَمَا يَذُوبُ الْمِلْحُ فِي الْمَاءِ ‏","","",""],[1508,1508,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏سَعْدٍ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَضْرِبُ بِإِحْدَى يَدَيْهِ عَلَى الْأُخْرَى وَهُوَ يَقُولُ ‏ ‏الشَّهْرُ هَكَذَا وَهَكَذَا ثُمَّ نَقَصَ أُصْبُعَهُ فِي الثَّالِثَةِ ‏","","",""],[1509,1509,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الشَّهْرُ هَكَذَا وَهَكَذَا عَشْرٌ وَعَشْرٌ وَتِسْعٌ مَرَّةً ‏","","",""],[1510,1510,"","","‏ ‏حَدَّثَنَا ‏ ‏الطَّالَقَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّهْرُ هَكَذَا وَهَكَذَا وَهَكَذَا ‏ ‏يَعْنِي تِسْعًا وَعِشْرِينَ ‏","","",""],[1511,1511,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي الدَّرَاوَرْدِيَّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَخْرُجَ قَوْمٌ يَأْكُلُونَ بِأَلْسِنَتِهِمْ كَمَا يَأْكُلُ الْبَقَرُ بِأَلْسِنَتِهَا ‏","","",""],[1512,1512,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ الْمُهَاجِرِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ يَعْنِي ابْنَ حَفْصٍ ‏ ‏فَذَكَرَ قِصَّةً ‏ ‏قَالَ ‏ ‏سَعْدٌ ‏ ‏إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏نِعْمَ الْمِيتَةُ أَنْ يَمُوتَ الرَّجُلُ دُونَ حَقِّهِ ‏","","",""],[1513,1513,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ يَعْنِي ابْنَ حَازِمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏جَرِيرٍ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏سَعْدٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أُوصِي بِمَالِي كُلِّهِ قَالَ لَا قُلْتُ فَثُلُثَيْهِ قَالَ لَا قُلْتُ فَنِصْفَهُ قَالَ لَا قُلْتُ فَالثُّلُثَ قَالَ ‏ ‏الثُّلُثَ وَالثُّلُثُ كَبِيرٌ أَحَدُكُمْ يَدَعُ أَهْلَهُ بِخَيْرٍ خَيْرٌ لَهُ مِنْ أَنْ يَدَعَهُمْ عَالَةً عَلَى أَيْدِي النَّاسِ ‏","","",""],[1514,1514,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏قَالَ ‏ ‏لَمَّا خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏خَلَّفَ ‏ ‏عَلِيًّا ‏ ‏فَقَالَ لَهُ أَتُخَلِّفُنِي قَالَ لَهُ ‏ ‏أَمَا ‏ ‏تَرْضَى أَنْ تَكُونَ مِنِّي بِمَنْزِلَةِ ‏ ‏هَارُونَ ‏ ‏مِنْ ‏ ‏مُوسَى ‏ ‏إِلَّا أَنَّهُ لَا نَبِيَّ بَعْدِي ‏","","",""],[1515,1515,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏أَنَّ ‏ ‏سَعْدًا ‏ ‏قَالَ فِي مَرَضِهِ إِذَا أَنَا مُتُّ ‏ ‏فَالْحَدُوا لِي ‏ ‏لَحْدًا ‏ ‏وَاصْنَعُوا مِثْلَ مَا صُنِعَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1516,1516,"","","‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ سَلَمَةَ الْخُزَاعِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏قَالَ ‏ ‏الْحَدُوا لِي لَحْدًا وَانْصِبُوا عَلَيَّ نَصْبًا كَمَا صُنِعَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1517,1517,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو شِهَابٍ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏طُفْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمِنَّا مَنْ طَافَ سَبْعًا وَمِنَّا مَنْ طَافَ ثَمَانِيًا وَمِنَّا مَنْ طَافَ أَكْثَرَ مِنْ ذَلِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏حَرَجَ ‏","","",""],[1518,1518,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏أَنْبَأَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو صَخْرٍ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مَنْ ‏ ‏هَارُونَ ‏ ‏أَنَّ ‏ ‏أَبَا حَازِمٍ ‏ ‏حَدَّثَهُ عَنِ ‏ ‏ابْنٍ لِسَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ ‏ ‏إِنَّ الْإِيمَانَ بَدَأَ غَرِيبًا وَسَيَعُودُ كَمَا بَدَأَ ‏ ‏فَطُوبَى ‏ ‏يَوْمَئِذٍ لِلْغُرَبَاءِ إِذَا فَسَدَ النَّاسُ وَالَّذِي نَفْسُ ‏ ‏أَبِي الْقَاسِمِ ‏ ‏بِيَدِهِ ‏ ‏لَيَأْرِزَنَّ ‏ ‏الْإِيمَانُ بَيْنَ هَذَيْنِ الْمَسْجِدَيْنِ كَمَا ‏ ‏تَأْرِزُ ‏ ‏الْحَيَّةُ فِي جُحْرِهَا ‏","","",""],[1519,1519,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَنْبَأَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الْقَرَّاظِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا خَيْرٌ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏","","",""],[1520,1520,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏أَنْبَأَنَا ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ ‏ ‏حَدَّثَنِي ‏ ‏عَامِرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أُحَرِّمُ مَا بَيْنَ ‏ ‏لَابَتَيْ ‏ ‏الْمَدِينَةِ ‏ ‏كَمَا حَرَّمَ ‏ ‏إِبْرَاهِيمُ ‏ ‏حَرَمَهُ لَا يُقْطَعُ ‏ ‏عِضَاهُهَا ‏ ‏وَلَا يُقْتَلُ صَيْدُهَا وَلَا يَخْرُجُ مِنْهَا أَحَدٌ رَغْبَةً عَنْهَا إِلَّا أَبْدَلَهَا اللَّهُ خَيْرًا مِنْهُ ‏ ‏وَالْمَدِينَةُ ‏ ‏خَيْرٌ لَهُمْ لَوْ كَانُوا يَعْلَمُونَ وَلَا يُرِيدُهُمْ أَحَدٌ بِسُوءٍ إِلَّا أَذَابَهُ اللَّهُ ذَوْبَ الرَّصَاصِ فِي النَّارِ أَوْ ذَوْبَ الْمِلْحِ فِي الْمَاءِ ‏","","",""],[1521,1521,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏حَدَّثَنِي ‏ ‏مُصْعَبُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ النَّاسِ أَشَدُّ بَلَاءً قَالَ فَقَالَ ‏ ‏الْأَنْبِيَاءُ ثُمَّ الْأَمْثَلُ فَالْأَمْثَلُ ‏ ‏يُبْتَلَى الرَّجُلُ عَلَى حَسَبِ دِينِهِ فَإِنْ كَانَ دِينُهُ صُلْبًا اشْتَدَّ بَلَاؤُهُ وَإِنْ كَانَ فِي دِينِهِ رِقَّةٌ ابْتُلِيَ عَلَى حَسَبِ دِينِهِ فَمَا ‏ ‏يَبْرَحُ ‏ ‏الْبَلَاءُ بِالْعَبْدِ حَتَّى يَتْرُكَهُ يَمْشِي عَلَى الْأَرْضِ مَا عَلَيْهِ خَطِيئَةٌ ‏","","",""],[1522,1522,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَاتِمُ بْنُ إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ مِسْمَارٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ لَهُ وَخَلَّفَهُ فِي بَعْضِ مَغَازِيهِ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏أَتُخَلِّفُنِي مَعَ النِّسَاءِ وَالصِّبْيَانِ قَالَ يَا ‏ ‏عَلِيُّ ‏ ‏أَمَا ‏ ‏تَرْضَى أَنْ تَكُونَ مِنِّي بِمَنْزِلَةِ ‏ ‏هَارُونَ ‏ ‏مِنْ ‏ ‏مُوسَى ‏ ‏إِلَّا أَنَّهُ لَا نُبُوَّةَ بَعْدِي وَسَمِعْتُهُ يَقُولُ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏لَأُعْطِيَنَّ ‏ ‏الرَّايَةَ ‏ ‏رَجُلًا يُحِبُّ اللَّهَ وَرَسُولَهُ وَيُحِبُّهُ اللَّهُ وَرَسُولُهُ ‏ ‏فَتَطَاوَلْنَا ‏ ‏لَهَا فَقَالَ ادْعُوا لِي ‏ ‏عَلِيًّا ‏ ‏فَأُتِيَ بِهِ ‏ ‏أَرْمَدَ ‏ ‏فَبَصَقَ فِي عَيْنِهِ وَدَفَعَ الرَّايَةَ إِلَيْهِ فَفَتَحَ اللَّهُ عَلَيْهِ وَلَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏نَدْعُ أَبْنَاءَنَا وَأَبْنَاءَكُمْ ‏} ‏دَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلِيًّا ‏ ‏وَفَاطِمَةَ ‏ ‏وَحَسَنًا ‏ ‏وَحُسَيْنًا ‏ ‏فَقَالَ اللَّهُمَّ هَؤُلَاءِ أَهْلِي ‏","","",""],[1523,1523,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَيَّاشِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏أَنَّ ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏قَالَ عِنْدَ فِتْنَةِ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏أَشْهَدُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّهَا ‏ ‏سَتَكُونُ فِتْنَةٌ الْقَاعِدُ فِيهَا خَيْرٌ مِنْ الْقَائِمِ وَالْقَائِمُ خَيْرٌ مِنْ الْمَاشِي وَالْمَاشِي خَيْرٌ مِنْ السَّاعِي قَالَ أَفَرَأَيْتَ إِنْ دَخَلَ عَلَيَّ بَيْتِي فَبَسَطَ يَدَهُ إِلَيَّ لِيَقْتُلَنِي قَالَ كُنْ كَابْنِ ‏ ‏آدَمَ ‏","","",""],[1524,1524,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ طَلْحَةَ التَّيْمِيُّ ‏ ‏مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سُهَيْلٍ نَافِعُ بْنُ مَالِكٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْعَبَّاسِ ‏ ‏هَذَا ‏ ‏الْعَبَّاسُ بْنُ عَبْدِ الْمُطَّلِبِ ‏ ‏أَجْوَدُ ‏ ‏قُرَيْشٍ ‏ ‏كَفًّا ‏ ‏وَأَوْصَلُهَا ‏","","",""],[1525,1525,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏وَيَعْلَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُوسَى يَعْنِي الْجُهَنِيَّ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏جَاءَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْرَابِيٌّ فَقَالَ يَا نَبِيَّ اللَّهِ عَلِّمْنِي كَلَامًا أَقُولُهُ قَالَ قُلْ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ اللَّهُ أَكْبَرُ كَبِيرًا وَالْحَمْدُ لِلَّهِ كَثِيرًا سُبْحَانَ اللَّهِ رَبِّ الْعَالَمِينَ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَزِيزِ الْحَكِيمِ قَالَ هَؤُلَاءِ لِرَبِّي عَزَّ وَجَلَّ فَمَا لِي قَالَ قُلْ اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَاهْدِنِي وَارْزُقْنِي ‏ ‏قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ ‏ ‏مُوسَى ‏ ‏أَمَّا عَافِنِي فَأَنَا أَتَوَهَّمُ وَمَا أَدْرِي ‏","","",""],[1526,1526,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَيَعْجِزُ أَحَدُكُمْ أَنْ يَكْسِبَ كُلَّ يَوْمٍ أَلْفَ حَسَنَةٍ قَالَ فَسَأَلَهُ سَائِلٌ مِنْ جُلَسَائِهِ يَا نَبِيَّ اللَّهِ كَيْفَ يَكْسِبُ أَحَدُنَا أَلْفَ حَسَنَةٍ قَالَ ‏ ‏يُسَبِّحُ مِائَةَ تَسْبِيحَةٍ فَيُكْتَبُ لَهُ أَلْفُ حَسَنَةٍ أَوْ يُحَطُّ عَنْهُ أَلْفُ خَطِيئَةٍ ‏","","",""],[1527,1527,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَيَعْجِزُ أَحَدُكُمْ أَنْ يَكْسِبَ كُلَّ يَوْمٍ أَلْفَ حَسَنَةٍ فَسَأَلَهُ سَائِلٌ مِنْ جُلَسَائِهِ كَيْفَ يَكْسِبُ أَحَدُنَا يَا رَسُولَ اللَّهِ كُلَّ يَوْمٍ أَلْفَ حَسَنَةٍ قَالَ ‏ ‏يُسَبِّحُ مِائَةَ تَسْبِيحَةٍ فَيُكْتَبُ لَهُ أَلْفُ حَسَنَةٍ أَوْ يُحَطُّ عَنْهُ أَلْفُ خَطِيئَةٍ ‏","","",""],[1528,1528,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أُنْزِلَتْ فِيَّ أَرْبَعُ آيَاتٍ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏أَصَبْتُ سَيْفًا فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏نَفِّلْنِيهِ ‏ ‏فَقَالَ ضَعْهُ ثُمَّ ‏ ‏قَامَ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏نَفِّلْنِيهِ ‏ ‏فَقَالَ ضَعْهُ ثُمَّ قَامَ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏نَفِّلْنِيهِ ‏ ‏أُجْعَلْ كَمَنْ لَا ‏ ‏غَنَاءَ ‏ ‏لَهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَعْهُ مِنْ حَيْثُ أَخَذْتَهُ فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏يَسْأَلُونَكَ عَنْ ‏ ‏الْأَنْفَالِ ‏ ‏قُلْ ‏ ‏الْأَنْفَالُ ‏ ‏لِلَّهِ وَالرَّسُولِ ‏} ‏قَالَ وَصَنَعَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏طَعَامًا فَدَعَانَا فَشَرِبْنَا الْخَمْرَ حَتَّى ‏ ‏انْتَشَيْنَا ‏ ‏قَالَ فَتَفَاخَرَتْ ‏ ‏الْأَنْصَارُ ‏ ‏وَقُرَيْشٌ ‏ ‏فَقَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏نَحْنُ أَفْضَلُ مِنْكُمْ وَقَالَتْ ‏ ‏قُرَيْشٌ ‏ ‏نَحْنُ أَفْضَلُ مِنْكُمْ فَأَخَذَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏لَحْيَيْ ‏ ‏جَزُورٍ ‏ ‏فَضَرَبَ بِهِ أَنْفَ ‏ ‏سَعْدٍ ‏ ‏فَفَزَرَهُ ‏ ‏قَالَ فَكَانَ أَنْفُ ‏ ‏سَعْدٍ ‏ ‏مَفْزُورًا ‏ ‏قَالَ فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ ‏ ‏وَالْأَنْصَابُ ‏ ‏وَالْأَزْلَامُ ‏ ‏رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ ‏} ‏قَالَ وَقَالَتْ ‏ ‏أُمُّ سَعْدٍ ‏ ‏أَلَيْسَ اللَّهُ قَدْ أَمَرَهُمْ بِالْبِرِّ فَوَاللَّهِ لَا أَطْعَمُ طَعَامًا وَلَا أَشْرَبُ شَرَابًا حَتَّى أَمُوتَ أَوْ تَكْفُرَ ‏ ‏بِمُحَمَّدٍ ‏ ‏قَالَ فَكَانُوا إِذَا أَرَادُوا أَنْ يُطْعِمُوهَا ‏ ‏شَجَرُوا ‏ ‏فَاهَا بِعَصًا ثُمَّ ‏ ‏أَوْجَرُوهَا ‏ ‏قَالَ فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏وَوَصَّيْنَا الْإِنْسَانَ بِوَالِدَيْهِ حُسْنًا ‏} ‏قَالَ وَدَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏سَعْدٍ ‏ ‏وَهُوَ مَرِيضٌ يَعُودُهُ فَقَالَ يَا رَسُولَ اللَّهِ أُوصِي بِمَالِي كُلِّهِ قَالَ لَا قَالَ فَبِثُلُثَيْهِ فَقَالَ لَا قَالَ فَبِثُلُثِهِ قَالَ فَسَكَتَ ‏","","",""],[1529,1529,"","","‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ عَمْرٍو الْكَلْبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏الْحَضْرَمِيِّ بْنِ لَاحِقٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ الطَّاعُونُ بِأَرْضٍ فَلَا تَهْبِطُوا عَلَيْهِ وَإِذَا كَانَ بِأَرْضٍ وَأَنْتُمْ بِهَا فَلَا تَفِرُّوا مِنْهُ ‏","","",""],[1530,1530,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ ‏ ‏أُحُدٍ ‏ ‏ارْمِهْ فِدَاكَ أَبِي وَأُمِّي ‏","","",""],[1531,1531,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عُبَيْدٍ الْبَهْرَانِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏وَكَانَ يَتَوَضَّأُ بِالزَّاوِيَةِ ‏ ‏فَخَرَجَ عَلَيْنَا ذَاتَ يَوْمٍ مِنْ الْبَرَازِ فَتَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ فَتَعَجَّبْنَا وَقُلْنَا مَا هَذَا قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ مِثْلَ مَا فَعَلْتُ ‏","","",""],[1532,1532,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعْدَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏وَاللَّهِ إِنِّي لَأَوَّلُ ‏ ‏الْعَرَبِ ‏ ‏رَمَى بِسَهْمٍ فِي سَبِيلِ اللَّهِ لَقَدْ ‏ ‏كُنَّا نَغْزُو مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا لَنَا طَعَامٌ نَأْكُلُهُ إِلَّا ‏ ‏وَرَقَ الْحُبْلَةِ ‏ ‏وَهَذَا ‏ ‏السَّمُرَ ‏ ‏حَتَّى إِنَّ أَحَدَنَا لَيَضَعُ كَمَا تَضَعُ الشَّاةُ مَالَهُ ‏ ‏خِلْطٌ ‏ ‏ثُمَّ أَصْبَحَتْ ‏ ‏بَنُو أَسَدٍ ‏ ‏يُعَزِّرُونِي ‏ ‏عَلَى الدِّينِ لَقَدْ خِبْتُ إِذَنْ وَضَلَّ عَمَلِي ‏","","",""],[1533,1533,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ ‏","","",""],[1534,1534,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ مُحَمَّدِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏الْخَنْدَقِ ‏ ‏وَرَجُلٌ ‏ ‏يَتَتَرَّسُ ‏ ‏جَعَلَ يَقُولُ ‏ ‏بِالتُّرْسِ ‏ ‏هَكَذَا فَوَضَعَهُ فَوْقَ أَنْفِهِ ثُمَّ يَقُولُ هَكَذَا يُسَفِّلُهُ بَعْدُ قَالَ فَأَهْوَيْتُ إِلَى ‏ ‏كِنَانَتِي ‏ ‏فَأَخْرَجْتُ مِنْهَا سَهْمًا ‏ ‏مُدَمًّا ‏ ‏فَوَضَعْتُهُ فِي ‏ ‏كَبِدِ ‏ ‏الْقَوْسِ فَلَمَّا قَالَ هَكَذَا يُسَفِّلُ ‏ ‏التُّرْسَ ‏ ‏رَمَيْتُ فَمَا نَسِيتُ وَقْعَ ‏ ‏الْقِدْحِ ‏ ‏عَلَى كَذَا وَكَذَا مِنْ ‏ ‏التُّرْسِ ‏ ‏قَالَ وَسَقَطَ فَقَالَ بِرِجْلِهِ ‏ ‏فَضَحِكَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْسِبُهُ قَالَ حَتَّى بَدَتْ ‏ ‏نَوَاجِذُهُ ‏ ‏قَالَ قُلْتُ لِمَ قَالَ لِفِعْلِ الرَّجُلِ ‏","","",""],[1535,1535,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُصْعَبَ بْنَ سَعْدٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَنَّهُ كَانَ يَأْمُرُ بِهَذَا الدُّعَاءِ وَيُحَدِّثُ بِهِ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْبُخْلِ وَأَعُوذُ بِكَ مِنْ الْجُبْنِ وَأَعُوذُ بِكَ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ ‏","","",""],[1536,1536,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّي ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ حَلَفَ ‏ ‏بِاللَّاتِ ‏ ‏وَالْعُزَّى ‏ ‏فَقَالَ لَهُ أَصْحَابُهُ قَدْ قُلْتَ هُجْرًا فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ الْعَهْدَ كَانَ حَدِيثًا وَإِنِّي حَلَفْتُ ‏ ‏بِاللَّاتِ ‏ ‏وَالْعُزَّى ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ ثَلَاثًا وَاتْفُلْ عَنْ شِمَالِكَ ثَلَاثًا وَتَعَوَّذْ بِاللَّهِ مِنْ الشَّيْطَانِ وَلَا تَعُدْ ‏","","",""],[1537,1537,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ابْنِ لَبِيبَةَ ‏ ‏أَنَّ ‏ ‏سَعْدَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏خَيْرُ الذِّكْرِ الْخَفِيُّ وَخَيْرُ الرِّزْقِ مَا يَكْفِي ‏","","",""],[1538,1538,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏اسْتَأْذَنَ ‏ ‏عُمَرُ ‏ ‏عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعِنْدَهُ جَوَارٍ قَدْ عَلَتْ أَصْوَاتُهُنَّ عَلَى صَوْتِهِ فَأَذِنَ لَهُ فَبَادَرْنَ فَذَهَبْنَ فَدَخَلَ ‏ ‏عُمَرُ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَضْحَكُ فَقَالَ ‏ ‏عُمَرُ ‏ ‏أَضْحَكَ اللَّهُ سِنَّكَ يَا رَسُولَ اللَّهِ بِأَبِي أَنْتَ وَأُمِّي قَالَ قَدْ عَجِبْتُ لِجَوَارٍ كُنَّ عِنْدِي فَلَمَّا سَمِعْنَ حِسَّكَ بَادَرْنَ فَذَهَبْنَ فَأَقْبَلَ عَلَيْهِنَّ فَقَالَ أَيْ عَدُوَّاتِ أَنْفُسِهِنَّ وَاللَّهِ لَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُنْتُنَّ أَحَقَّ أَنْ تَهَبْنَ مِنِّي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهُنَّ عَنْكَ يَا ‏ ‏عُمَرُ ‏ ‏فَوَاللَّهِ ‏ ‏إِنْ لَقِيَكَ الشَّيْطَانُ ‏ ‏بِفَجٍّ ‏ ‏قَطُّ إِلَّا أَخَذَ ‏ ‏فَجًّا ‏ ‏غَيْرَ ‏ ‏فَجِّكَ ‏ ‏آخِرُ حَدِيثِ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[1539,1539,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الْمَلِكِ بْنَ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ حُرَيْثٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدِ بْنِ عَمْرِو بْنِ نُفَيْلٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْكَمْأَةُ ‏ ‏مِنْ ‏ ‏الْمَنِّ ‏ ‏وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ ‏","","",""],[1540,1540,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ حُرَيْثٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكَمْأَةُ ‏ ‏مِنْ ‏ ‏الْمَنِّ ‏ ‏وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ ‏","","",""],[1541,1541,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ حُرَيْثٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْكَمْأَةُ مِنْ السَّلْوَى وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ ‏","","",""],[1542,1542,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏هَذَا حَفِظْنَاهُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عَبْدِ اللَّهِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدِ بْنِ عَمْرِو بْنِ نُفَيْلٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قُتِلَ دُونَ مَالِهِ فَهُوَ شَهِيدٌ وَمَنْ ظَلَمَ مِنْ الْأَرْضِ شِبْرًا ‏ ‏طُوِّقَهُ ‏ ‏مِنْ سَبْعِ أَرَضِينَ ‏","","",""],[1543,1543,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏صَدَقَةَ بْنِ الْمُثَنَّى ‏ ‏حَدَّثَنِي ‏ ‏جَدِّي ‏ ‏رِيَاحُ بْنُ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏كَانَ فِي الْمَسْجِدِ الْأَكْبَرِ وَعِنْدَهُ أَهْلُ ‏ ‏الْكُوفَةِ ‏ ‏عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ فَجَاءَهُ رَجُلٌ يُدْعَى ‏ ‏سَعِيدَ بْنَ زَيْدٍ ‏ ‏فَحَيَّاهُ ‏ ‏الْمُغِيرَةُ ‏ ‏وَأَجْلَسَهُ عِنْدَ رِجْلَيْهِ عَلَى السَّرِيرِ فَجَاءَ رَجُلٌ مِنْ أَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏فَاسْتَقْبَلَ ‏ ‏الْمُغِيرَةَ ‏ ‏فَسَبَّ وَسَبَّ فَقَالَ مَنْ يَسُبُّ هَذَا يَا ‏ ‏مُغِيرَةُ ‏ ‏قَالَ يَسُبُّ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏قَالَ يَا ‏ ‏مُغِيرَ بْنَ شُعْبَ ‏ ‏يَا ‏ ‏مُغِيرَ بْنَ شُعْبَ ‏ ‏ثَلَاثًا أَلَا أَسْمَعُ ‏ ‏أَصْحَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَبُّونَ عِنْدَكَ لَا تُنْكِرُ وَلَا تُغَيِّرُ فَأَنَا أَشْهَدُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَا سَمِعَتْ أُذُنَايَ وَوَعَاهُ قَلْبِي مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنِّي لَمْ أَكُنْ ‏ ‏أَرْوِي عَنْهُ كَذِبًا يَسْأَلُنِي عَنْهُ إِذَا لَقِيتُهُ أَنَّهُ قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعُمَرُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعَلِيٌّ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعُثْمَانُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَطَلْحَةُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَالزُّبَيْرُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَسَعْدُ بْنُ مَالِكٍ ‏ ‏فِي الْجَنَّةِ وَتَاسِعُ الْمُؤْمِنِينَ فِي الْجَنَّةِ لَوْ شِئْتُ أَنْ أُسَمِّيَهُ لَسَمَّيْتُهُ قَالَ فَضَجَّ أَهْلُ الْمَسْجِدِ ‏ ‏يُنَاشِدُونَهُ ‏ ‏يَا صَاحِبَ رَسُولِ اللَّهِ مَنْ التَّاسِعُ قَالَ ‏ ‏نَاشَدْتُمُونِي ‏ ‏بِاللَّهِ وَاللَّهِ الْعَظِيمِ أَنَا تَاسِعُ الْمُؤْمِنِينَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَاشِرُ ثُمَّ أَتْبَعَ ذَلِكَ يَمِينًا قَالَ وَاللَّهِ لَمَشْهَدٌ شَهِدَهُ رَجُلٌ يُغَبِّرُ فِيهِ وَجْهَهُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُ مِنْ عَمَلِ أَحَدِكُمْ وَلَوْ عُمِّرَ عُمُرَ ‏ ‏نُوحٍ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[1544,1544,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏وَمَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏مَرَّةً ‏ ‏قَالَ ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدٍ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏حُصَيْنٌ ‏ ‏عَنِ ‏ ‏ابْنِ ظَالِمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اسْكُنْ ‏ ‏حِرَاءُ ‏ ‏فَلَيْسَ عَلَيْكَ إِلَّا نَبِيٌّ أَوْ صِدِّيقٌ أَوْ شَهِيدٌ قَالَ وَعَلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏وَعَلِيٌّ ‏ ‏وَطَلْحَةُ ‏ ‏وَالزُّبَيْرُ ‏ ‏وَسَعْدٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏وَسَعِيدُ بْنُ زَيْدٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏","","",""],[1545,1545,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحُرِّ بْنِ الصَّيَّاحِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَخْنَسِ ‏ ‏قَالَ ‏ ‏خَطَبَنَا ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏فَنَالَ مِنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَامَ ‏ ‏سَعِيدُ بْنُ زَيْدٍ ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏النَّبِيُّ فِي الْجَنَّةِ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعُمَرُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعُثْمَانُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعَلِيٌّ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَطَلْحَةُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَالزُّبَيْرُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَسَعْدٌ ‏ ‏فِي الْجَنَّةِ وَلَوْ شِئْتُ أَنْ أُسَمِّيَ الْعَاشِرَ ‏","","",""],[1546,1546,"","","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ حُرَيْثٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْكَمْأَةُ ‏ ‏مِنْ ‏ ‏الْمَنِّ ‏ ‏وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ ‏","","",""],[1547,1547,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَخَذَ شِبْرًا مِنْ الْأَرْضِ ظُلْمًا ‏ ‏طُوِّقَهُ ‏ ‏يَوْمَ الْقِيَامَةِ إِلَى سَبْعِ أَرَضِينَ ‏ ‏قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏مِنْ سَبْعِ أَرَضِينَ ‏","","",""],[1548,1548,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ حُرَيْثٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏خَرَجَ إِلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفِي يَدِهِ ‏ ‏كَمْأَةٌ ‏ ‏فَقَالَ ‏ ‏تَدْرُونَ مَا هَذَا هَذَا مِنْ ‏ ‏الْمَنِّ ‏ ‏وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ ‏","","",""],[1549,1549,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ حُرَيْثٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ زَيْدٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْكَمْأَةُ مِنْ ‏ ‏الْمَنِّ ‏ ‏وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏الْحَكَمُ بْنُ عُتَيْبَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ الْعُرَنِيِّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ حُرَيْثٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَمَّا حَدَّثَنِي بِهِ ‏ ‏الْحَكَمُ ‏ ‏لَمْ أُنْكِرْهُ مِنْ حَدِيثِ ‏ ‏عَبْدِ الْمَلِكِ ‏","","",""],[1550,1550,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحُرِّ بْنِ صَيَّاحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَخْنَسِ ‏ ‏أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏خَطَبَ فَنَالَ مِنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ فَقَامَ ‏ ‏سَعِيدُ بْنُ زَيْدٍ ‏ ‏فَقَالَ أَشْهَدُ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏رَسُولُ اللَّهِ فِي الْجَنَّةِ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعُمَرُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعَلِيٌّ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعُثْمَانُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَطَلْحَةُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَالزُّبَيْرُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَسَعْدٌ ‏ ‏فِي الْجَنَّةِ ‏ ‏ثُمَّ قَالَ إِنْ شِئْتُمْ أَخْبَرْتُكُمْ بِالْعَاشِرِ ثُمَّ ذَكَرَ نَفْسَهُ ‏","","",""],[1551,1551,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ ظَالِمٍ ‏ ‏قَالَ ‏ ‏خَطَبَ ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏فَنَالَ مِنْ ‏ ‏عَلِيٍّ ‏ ‏فَخَرَجَ ‏ ‏سَعِيدُ بْنُ زَيْدٍ ‏ ‏فَقَالَ أَلَا تَعْجَبُ مِنْ هَذَا يَسُبُّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَشْهَدُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّا كُنَّا عَلَى ‏ ‏حِرَاءٍ ‏ ‏أَوْ ‏ ‏أُحُدٍ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اثْبُتْ ‏ ‏حِرَاءُ ‏ ‏أَوْ ‏ ‏أُحُدُ ‏ ‏فَإِنَّمَا عَلَيْكَ صِدِّيقٌ أَوْ شَهِيدٌ فَسَمَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَشَرَةَ فَسَمَّى ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏وَعَلِيًّا ‏ ‏وَطَلْحَةَ ‏ ‏وَالزُّبَيْرَ ‏ ‏وَسَعْدًا ‏ ‏وَعَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏وَسَمَّى نَفْسَهُ ‏ ‏سَعِيدًا ‏","","",""],[1552,1552,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عَبْدِ اللَّهِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَهْلٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدِ بْنِ عَمْرِو بْنِ نُفَيْلٍ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ سَرَقَ مِنْ الْأَرْضِ شِبْرًا ‏ ‏طُوِّقَهُ ‏ ‏مِنْ سَبْعِ أَرَضِينَ ‏ ‏قَالَ ‏ ‏مَعْمَرٌ ‏ ‏وَبَلَغَنِي عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏وَلَمْ أَسْمَعْهُ مِنْهُ زَادَ فِي هَذَا الْحَدِيثِ وَمَنْ قُتِلَ دُونَ مَالِهِ فَهُوَ شَهِيدٌ ‏","","",""],[1553,1553,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏أَنَّ ‏ ‏مَرْوَانَ ‏ ‏قَالَ اذْهَبُوا فَأَصْلِحُوا بَيْنَ هَذَيْنِ ‏ ‏لِسَعِيدِ بْنِ زَيْدٍ ‏ ‏وَأَرْوَى ‏ ‏فَقَالَ ‏ ‏سَعِيدٌ ‏ ‏أَتُرَوْنِي أَخَذْتُ مِنْ حَقِّهَا شَيْئًا أَشْهَدُ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَخَذَ مِنْ الْأَرْضِ شِبْرًا بِغَيْرِ حَقِّهِ ‏ ‏طُوِّقَهُ ‏ ‏مِنْ سَبْعِ أَرَضِينَ وَمَنْ ‏ ‏تَوَلَّى ‏ ‏مَوْلَى قَوْمٍ بِغَيْرِ إِذْنِهِمْ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَمَنْ ‏ ‏اقْتَطَعَ ‏ ‏مَالَ امْرِئٍ مُسْلِمٍ بِيَمِينٍ فَلَا بَارَكَ ‏ ‏اللَّهُ ‏ ‏لَهُ فِيهَا ‏","","",""],[1554,1554,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏طَلْحَةُ بْنُ عَبْدِ اللَّهِ بْنِ عَوْفٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَمْرِو بْنِ سَهْلٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏سَعِيدَ بْنَ زَيْدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ظَلَمَ مِنْ الْأَرْضِ شِبْرًا فَإِنَّهُ ‏ ‏يُطَوَّقُهُ ‏ ‏مِنْ سَبْعِ أَرَضِينَ ‏","","",""],[1555,1555,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عَبْدِ اللَّهِ بْنِ عَوْفٍ ‏ ‏قَالَ ‏ ‏أَتَتْنِي ‏ ‏أَرْوَى بِنْتُ أُوَيْسٍ ‏ ‏فِي ‏ ‏نَفَرٍ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فِيهِمْ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَمْرِو بْنِ سَهْلٍ ‏ ‏فَقَالَتْ إِنَّ ‏ ‏سَعِيدَ بْنَ زَيْدٍ ‏ ‏قَدْ انْتَقَصَ مِنْ أَرْضِي إِلَى أَرْضِهِ مَا لَيْسَ لَهُ وَقَدْ أَحْبَبْتُ أَنْ تَأْتُوهُ فَتُكَلِّمُوهُ قَالَ فَرَكِبْنَا إِلَيْهِ وَهُوَ بِأَرْضِهِ ‏ ‏بِالْعَقِيقِ ‏ ‏فَلَمَّا رَآنَا قَالَ قَدْ عَرَفْتُ الَّذِي جَاءَ بِكُمْ وَسَأُحَدِّثُكُمْ مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعْتُهُ يَقُولُ ‏ ‏مَنْ أَخَذَ مِنْ الْأَرْضِ مَا لَيْسَ لَهُ ‏ ‏طُوِّقَهُ ‏ ‏إِلَى السَّابِعَةِ مِنْ الْأَرْضِ يَوْمَ الْقِيَامَةِ وَمَنْ قُتِلَ دُونَ مَالِهِ فَهُوَ شَهِيدٌ ‏","","",""],[1556,1556,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنِي ‏ ‏الزُّبَيْدِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عَبْدِ اللَّهِ بْنِ عَوْفٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَمْرِو بْنِ سَهْلٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏سَعِيدَ بْنَ زَيْدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ظَلَمَ مِنْ الْأَرْضِ شَيْئًا فَإِنَّهُ ‏ ‏يُطَوَّقُهُ ‏ ‏مِنْ سَبْعِ أَرَضِينَ ‏","","",""],[1557,1557,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏قَالَ ‏ ‏حُصَيْنٌ ‏ ‏أَخْبَرَنَا عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ ظَالِمٍ الْمَازِنِيِّ ‏ ‏قَالَ ‏ ‏لَمَّا خَرَجَ ‏ ‏مُعَاوِيَةُ ‏ ‏مِنْ ‏ ‏الْكُوفَةِ ‏ ‏اسْتَعْمَلَ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏قَالَ فَأَقَامَ خُطَبَاءَ يَقَعُونَ فِي ‏ ‏عَلِيٍّ ‏ ‏قَالَ وَأَنَا إِلَى جَنْبِ ‏ ‏سَعِيدِ بْنِ زَيْدِ بْنِ عَمْرِو بْنِ نُفَيْلٍ ‏ ‏قَالَ فَغَضِبَ فَقَامَ فَأَخَذَ بِيَدِي فَتَبِعْتُهُ فَقَالَ أَلَا ‏ ‏تَرَى إِلَى هَذَا الرَّجُلِ الظَّالِمِ لِنَفْسِهِ الَّذِي يَأْمُرُ بِلَعْنِ رَجُلٍ مِنْ أَهْلِ الْجَنَّةِ فَأَشْهَدُ عَلَى التِّسْعَةِ أَنَّهُمْ فِي الْجَنَّةِ وَلَوْ شَهِدْتُ عَلَى الْعَاشِرِ لَمْ ‏ ‏آثَمْ ‏ ‏قَالَ قُلْتُ وَمَا ذَاكَ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اثْبُتْ ‏ ‏حِرَاءُ ‏ ‏فَإِنَّهُ لَيْسَ عَلَيْكَ إِلَّا نَبِيٌّ أَوْ صِدِّيقٌ أَوْ شَهِيدٌ قَالَ قُلْتُ مَنْ هُمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏وَعَلِيٌّ ‏ ‏وَالزُّبَيْرُ ‏ ‏وَطَلْحَةُ ‏ ‏وَعَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏وَسَعْدُ بْنُ مَالِكٍ ‏ ‏قَالَ ثُمَّ سَكَتَ قَالَ قُلْتُ وَمَنْ الْعَاشِرُ قَالَ قَالَ أَنَا ‏","","",""],[1558,1558,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏حُصَيْنُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ ظَالِمٍ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدِ بْنِ عَمْرِو بْنِ نُفَيْلٍ ‏ ‏قَالَ ‏ ‏أَشْهَدُ أَنَّ ‏ ‏عَلِيًّا ‏ ‏مِنْ أَهْلِ الْجَنَّةِ قُلْتُ وَمَا ذَاكَ قَالَ هُوَ فِي التِّسْعَةِ وَلَوْ شِئْتُ أَنْ أُسَمِّيَ الْعَاشِرَ سَمَّيْتُهُ قَالَ اهْتَزَّ ‏ ‏حِرَاءٌ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اثْبُتْ ‏ ‏حِرَاءُ ‏ ‏فَإِنَّهُ لَيْسَ عَلَيْكَ إِلَّا نَبِيٌّ أَوْ صِدِّيقٌ أَوْ شَهِيدٌ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعَلِيٌّ ‏ ‏وَعُثْمَانُ ‏ ‏وَطَلْحَةُ ‏ ‏وَالزُّبَيْرُ ‏ ‏وَعَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏وَسَعْدٌ ‏ ‏وَأَنَا ‏ ‏يَعْنِي ‏ ‏سَعِيدًا ‏ ‏نَفْسَهُ ‏","","",""],[1559,1559,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏أَوْ ‏ ‏أَبُو أُوَيْسٍ ‏ ‏قَالَ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏طَلْحَةُ بْنُ عَبْدِ اللَّهِ بْنِ عَوْفٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَمْرِو بْنِ سَهْلٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏سَعِيدَ بْنَ زَيْدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ظَلَمَ مِنْ الْأَرْضِ شَيْئًا فَإِنَّهُ ‏ ‏يُطَوَّقُهُ ‏ ‏فِي سَبْعِ أَرَضِينَ ‏","","",""],[1560,1560,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏أَخْبَرَنِي ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ ظَالِمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِتَنًا كَقِطَعِ اللَّيْلِ الْمُظْلِمِ أُرَاهُ قَالَ قَدْ يَذْهَبُ فِيهَا النَّاسُ أَسْرَعَ ذَهَابٍ قَالَ فَقِيلَ أَكُلُّهُمْ هَالِكٌ أَمْ بَعْضُهُمْ قَالَ حَسْبُهُمْ ‏ ‏أَوْ بِحَسْبِهِمْ ‏ ‏الْقَتْلُ ‏","","",""],[1561,1561,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏نُفَيْلِ بْنِ هِشَامِ بْنِ سَعِيدِ بْنِ زَيْدِ بْنِ عَمْرِو بْنِ نُفَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَكَّةَ ‏ ‏هُوَ ‏ ‏وَزَيْدُ بْنُ حَارِثَةَ ‏ ‏فَمَرَّ بِهِمَا ‏ ‏زَيْدُ بْنُ عَمْرِو بْنِ نُفَيْلٍ ‏ ‏فَدَعَوَاهُ ‏ ‏إِلَى ‏ ‏سُفْرَةٍ ‏ ‏لَهُمَا فَقَالَ يَا ابْنَ أَخِي ‏ ‏إِنِّي لَا آكُلُ مِمَّا ذُبِحَ عَلَى ‏ ‏النُّصُبِ ‏ ‏قَالَ فَمَا رُئِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ ذَلِكَ أَكَلَ شَيْئًا مِمَّا ‏ ‏ذُبِحَ عَلَى ‏ ‏النُّصُبِ ‏ ‏قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ أَبِي كَانَ كَمَا قَدْ رَأَيْتَ وَبَلَغَكَ وَلَوْ أَدْرَكَكَ لَآمَنَ بِكَ وَاتَّبَعَكَ فَاسْتَغْفِرْ لَهُ قَالَ نَعَمْ فَأَسْتَغْفِرُ لَهُ فَإِنَّهُ يُبْعَثُ يَوْمَ الْقِيَامَةِ أُمَّةً وَاحِدَةً ‏","","",""],[1562,1562,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏قَالَ لَنَا ‏ ‏مَرْوَانُ ‏ ‏انْطَلِقُوا فَأَصْلِحُوا بَيْنَ هَذَيْنِ ‏ ‏سَعِيدِ بْنِ زَيْدٍ ‏ ‏وَأَرْوَى بِنْتِ أُوَيْسٍ ‏ ‏فَأَتَيْنَا ‏ ‏سَعِيدَ بْنَ زَيْدٍ ‏ ‏فَقَالَ أَتُرَوْنَ أَنِّي قَدْ اسْتَنْقَصْتُ مِنْ حَقِّهَا شَيْئًا أَشْهَدُ لَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَخَذَ شِبْرًا مِنْ الْأَرْضِ بِغَيْرِ حَقِّهِ ‏ ‏طُوِّقَهُ ‏ ‏مِنْ سَبْعِ أَرَضِينَ وَمَنْ تَوَلَّى قَوْمًا بِغَيْرِ إِذْنِهِمْ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَمَنْ ‏ ‏اقْتَطَعَ ‏ ‏مَالَ أَخِيهِ بِيَمِينِهِ فَلَا بَارَكَ اللَّهُ لَهُ فِيهِ ‏","","",""],[1563,1563,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ حُرَيْثٍ ‏ ‏قَالَ ‏ ‏قَدِمْتُ ‏ ‏الْمَدِينَةَ ‏ ‏فَقَاسَمْتُ أَخِي فَقَالَ ‏ ‏سَعِيدُ بْنُ زَيْدٍ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُبَارَكُ فِي ثَمَنِ أَرْضٍ وَلَا دَارٍ لَا يُجْعَلُ فِي أَرْضٍ وَلَا دَارٍ ‏","","",""],[1564,1564,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَنْبَأَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي حُسَيْنٍ ‏ ‏قَالَ ‏ ‏بَلَغَنِي أَنَّ ‏ ‏لُقْمَانَ ‏ ‏كَانَ يَقُولُ يَا بُنَيَّ لَا تَعَلَّمْ الْعِلْمَ لِتُبَاهِيَ بِهِ الْعُلَمَاءَ أَوْ ‏ ‏تُمَارِيَ ‏ ‏بِهِ ‏ ‏السُّفَهَاءَ ‏ ‏وَتُرَائِيَ ‏ ‏بِهِ فِي الْمَجَالِسِ فَذَكَرَهُ ‏ ‏وَقَالَ حَدَّثَنَا ‏ ‏نَوْفَلُ بْنُ مُسَاحِقٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مِنْ ‏ ‏أَرْبَى ‏ ‏الرِّبَا ‏ ‏الِاسْتِطَالَةُ ‏ ‏فِي عِرْضِ مُسْلِمٍ بِغَيْرِ حَقٍّ وَإِنَّ هَذِهِ ‏ ‏الرَّحِمَ ‏ ‏شِجْنَةٌ ‏ ‏مِنْ الرَّحْمَنِ فَمَنْ قَطَعَهَا حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ ‏","","",""],[1565,1565,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ مُحَمَّدِ بْنِ عَمَّارِ بْنِ يَاسِرٍ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عَبْدِ اللَّهِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قُتِلَ دُونَ مَالِهِ فَهُوَ شَهِيدٌ وَمَنْ قُتِلَ دُونَ أَهْلِهِ فَهُوَ شَهِيدٌ وَمَنْ قُتِلَ دُونَ دِينِهِ فَهُوَ شَهِيدٌ وَمَنْ قُتِلَ دُونَ دَمِهِ فَهُوَ شَهِيدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ مُحَمَّدِ بْنِ عَمَّارٍ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عَبْدِ اللَّهِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[1566,1566,"","","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏حَدَّثَنِي ‏ ‏مَنْ سَمِعَ ‏ ‏عَمْرَو بْنَ حُرَيْثٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يَا مَعْشَرَ ‏ ‏الْعَرَبِ ‏ ‏احْمَدُوا اللَّهَ الَّذِي رَفَعَ عَنْكُمْ ‏ ‏الْعُشُورَ ‏","","",""],[1567,1567,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏شَهِدْتُ ‏ ‏حِلْفَ الْمُطَيَّبِينَ ‏ ‏مَعَ عُمُومَتِي وَأَنَا غُلَامٌ فَمَا أُحِبُّ أَنَّ لِي حُمْرَ النَّعَمِ وَأَنِّي أَنْكُثُهُ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يُصِبْ الْإِسْلَامُ حِلْفًا إِلَّا زَادَهُ شِدَّةً وَلَا ‏ ‏حِلْفَ ‏ ‏فِي الْإِسْلَامِ وَقَدْ أَلَّفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏قُرَيْشٍ ‏ ‏وَالْأَنْصَارِ ‏","","",""],[1568,1568,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏يَا غُلَامُ هَلْ سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ مِنْ أَحَدٍ مِنْ أَصْحَابِهِ إِذَا شَكَّ الرَّجُلُ فِي صَلَاتِهِ مَاذَا يَصْنَعُ قَالَ فَبَيْنَا هُوَ كَذَلِكَ إِذْ أَقْبَلَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏فَقَالَ فِيمَ أَنْتُمَا فَقَالَ ‏ ‏عُمَرُ ‏ ‏سَأَلْتُ هَذَا الْغُلَامَ هَلْ سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ أَحَدٍ مِنْ أَصْحَابِهِ إِذَا شَكَّ الرَّجُلُ فِي صَلَاتِهِ مَاذَا يَصْنَعُ فَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا شَكَّ أَحَدُكُمْ فِي صَلَاتِهِ فَلَمْ يَدْرِ أَوَاحِدَةً صَلَّى أَمْ ثِنْتَيْنِ فَلْيَجْعَلْهَا وَاحِدَةً وَإِذَا لَمْ يَدْرِ ثِنْتَيْنِ صَلَّى أَمْ ثَلَاثًا فَلْيَجْعَلْهَا ثِنْتَيْنِ وَإِذَا لَمْ يَدْرِ أَثَلَاثًا صَلَّى أَمْ أَرْبَعًا فَلْيَجْعَلْهَا ثَلَاثًا ثُمَّ يَسْجُدْ إِذَا فَرَغَ مِنْ صَلَاتِهِ وَهُوَ جَالِسٌ قَبْلَ أَنْ يُسَلِّمَ سَجْدَتَيْنِ ‏","","",""],[1569,1569,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏سَمِعَ ‏ ‏بَجَالَةَ ‏ ‏يَقُولُ ‏ ‏كُنْتُ كَاتِبًا ‏ ‏لِجَزْءِ بْنِ مُعَاوِيَةَ ‏ ‏عَمِّ ‏ ‏الْأَحْنَفِ بْنِ قَيْسٍ ‏ ‏فَأَتَانَا كِتَابُ ‏ ‏عُمَرَ ‏ ‏قَبْلَ مَوْتِهِ بِسَنَةٍ أَنْ ‏ ‏اقْتُلُوا كُلَّ سَاحِرٍ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏سُفْيَانُ ‏ ‏وَسَاحِرَةٍ ‏ ‏وَفَرِّقُوا بَيْنَ كُلِّ ذِي ‏ ‏مَحْرَمٍ ‏ ‏مِنْ ‏ ‏الْمَجُوسِ ‏ ‏وَانْهَوْهُمْ عَنْ ‏ ‏الزَّمْزَمَةِ ‏ ‏فَقَتَلْنَا ثَلَاثَةَ سَوَاحِرَ وَجَعَلْنَا نُفَرِّقُ بَيْنَ الرَّجُلِ وَبَيْنَ حَرِيمَتِهِ فِي كِتَابِ اللَّهِ وَصَنَعَ ‏ ‏جَزْءٌ ‏ ‏طَعَامًا كَثِيرًا وَعَرَضَ السَّيْفَ عَلَى فَخِذِهِ وَدَعَا ‏ ‏الْمَجُوسَ ‏ ‏فَأَلْقَوْا ‏ ‏وِقْرَ ‏ ‏بَغْلٍ ‏ ‏أَوْ بَغْلَيْنِ ‏ ‏مِنْ ‏ ‏وَرِقٍ ‏ ‏وَأَكَلُوا مِنْ غَيْرِ ‏ ‏زَمْزَمَةٍ ‏ ‏وَلَمْ يَكُنْ ‏ ‏عُمَرُ ‏ ‏أَخَذَ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏سُفْيَانُ ‏ ‏قَبِلَ ‏ ‏الْجِزْيَةَ ‏ ‏مِنْ ‏ ‏الْمَجُوسِ ‏ ‏حَتَّى شَهِدَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذَهَا مِنْ ‏ ‏مَجُوسِ هَجَرَ ‏ ‏و قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏حَجَّ ‏ ‏بَجَالَةُ ‏ ‏مَعَ ‏ ‏مُصْعَبٍ ‏ ‏سَنَةَ سَبْعِينَ ‏","","",""],[1570,1570,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَوْسٍ ‏ ‏سَمِعْتُ ‏ ‏عُمَرَ ‏ ‏يَقُولُ ‏ ‏لِعَبْدِ الرَّحْمَنِ ‏ ‏وَطَلْحَةَ ‏ ‏وَالزُّبَيْرِ ‏ ‏وَسَعْدٍ ‏ ‏نَشَدْتُكُمْ بِاللَّهِ الَّذِي تَقُومُ بِهِ السَّمَاءُ وَالْأَرْضُ ‏ ‏وَقَالَ ‏ ‏مَرَّةً الَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالْأَرْضُ ‏ ‏أَعَلِمْتُمْ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّا لَا نُورَثُ مَا تَرَكْنَا صَدَقَةٌ قَالُوا اللَّهُمَّ نَعَمْ ‏","","",""],[1571,1571,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ قَارِظٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّهُ دَخَلَ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏وَهُوَ مَرِيضٌ فَقَالَ لَهُ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَصَلَتْكَ ‏ ‏رَحِمٌ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَنَا الرَّحْمَنُ خَلَقْتُ ‏ ‏الرَّحِمَ ‏ ‏وَشَقَقْتُ لَهَا مِنْ اسْمِي فَمَنْ يَصِلْهَا أَصِلْهُ وَمَنْ يَقْطَعْهَا أَقْطَعْهُ فَأَبُتَّهُ ‏ ‏أَوْ قَالَ مَنْ ‏ ‏يَبُتَّهَا ‏ ‏أَبُتَّهُ ‏","","",""],[1572,1572,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ الْفَضْلِ ‏ ‏حَدَّثَنَا ‏ ‏النَّضْرُ بْنُ شَيْبَانَ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏قُلْتُ حَدِّثْنِي عَنْ شَيْءٍ سَمِعْتَهُ مِنْ أَبِيكَ سَمِعَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي شَهْرِ رَمَضَانَ قَالَ نَعَمْ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ فَرَضَ صِيَامَ رَمَضَانَ وَسَنَنْتُ قِيَامَهُ فَمَنْ صَامَهُ وَقَامَهُ ‏ ‏احْتِسَابًا ‏ ‏خَرَجَ مِنْ الذُّنُوبِ كَيَوْمِ وَلَدَتْهُ أُمُّهُ ‏","","",""],[1573,1573,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي جَعْفَرٍ ‏ ‏أَنَّ ‏ ‏ابْنَ قَارِظٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّتْ الْمَرْأَةُ خَمْسَهَا وَصَامَتْ شَهْرَهَا وَحَفِظَتْ فَرْجَهَا وَأَطَاعَتْ زَوْجَهَا قِيلَ لَهَا ادْخُلِي ‏ ‏الْجَنَّةَ مِنْ أَيِّ أَبْوَابِ الْجَنَّةِ شِئْتِ ‏","","",""],[1574,1574,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ مَنْصُورُ بْنُ سَلَمَةَ الْخُزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي الْحُوَيْرِثِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاتَّبَعْتُهُ حَتَّى دَخَلَ ‏ ‏نَخْلًا ‏ ‏فَسَجَدَ فَأَطَالَ السُّجُودَ حَتَّى خِفْتُ ‏ ‏أَوْ خَشِيتُ ‏ ‏أَنْ يَكُونَ اللَّهُ قَدْ تَوَفَّاهُ ‏ ‏أَوْ قَبَضَهُ ‏ ‏قَالَ فَجِئْتُ أَنْظُرُ فَرَفَعَ رَأْسَهُ فَقَالَ مَا لَكَ يَا ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏قَالَ فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ ‏ ‏إِنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ لِي أَلَا أُبَشِّرُكَ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ لَكَ مَنْ صَلَّى عَلَيْكَ صَلَّيْتُ عَلَيْهِ وَمَنْ سَلَّمَ عَلَيْكَ سَلَّمْتُ عَلَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ أَبِي الْحُوَيْرِثِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ الْمَسْجِدَ فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَارِجًا مِنْ الْمَسْجِدِ فَاتَّبَعْتُهُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[1575,1575,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ الْوَاحِدِ بْنِ مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَوَجَّهَ نَحْوَ ‏ ‏صَدَقَتِهِ ‏ ‏فَدَخَلَ فَاسْتَقْبَلَ الْقِبْلَةَ ‏ ‏فَخَرَّ ‏ ‏سَاجِدًا فَأَطَالَ السُّجُودَ حَتَّى ظَنَنْتُ أَنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ قَبَضَ نَفْسَهُ فِيهَا ‏ ‏فَدَنَوْتُ ‏ ‏مِنْهُ فَجَلَسْتُ فَرَفَعَ رَأْسَهُ فَقَالَ مَنْ هَذَا قُلْتُ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ مَا شَأْنُكَ قُلْتُ يَا رَسُولَ اللَّهِ سَجَدْتَ سَجْدَةً خَشِيتُ أَنْ يَكُونَ اللَّهُ عَزَّ وَجَلَّ قَدْ قَبَضَ نَفْسَكَ فِيهَا فَقَالَ ‏ ‏إِنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَتَانِي فَبَشَّرَنِي فَقَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ مَنْ صَلَّى عَلَيْكَ صَلَّيْتُ عَلَيْهِ وَمَنْ سَلَّمَ عَلَيْكَ سَلَّمْتُ عَلَيْهِ فَسَجَدْتُ لِلَّهِ عَزَّ وَجَلَّ شُكْرًا ‏","","",""],[1576,1576,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمُ بْنُ خَارِجَةَ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏يَعْنِي ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏الْهَيْثَمِ بْنِ خَارِجَةَ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْوَلِيدِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ كَانَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَذَهَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحَاجَتِهِ فَأَدْرَكَهُمْ وَقْتُ الصَّلَاةِ فَأَقَامُوا الصَّلَاةَ فَتَقَدَّمَهُمْ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فَجَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى مَعَ النَّاسِ خَلْفَهُ رَكْعَةً فَلَمَّا سَلَّمَ قَالَ ‏ ‏أَصَبْتُمْ ‏ ‏أَوْ أَحْسَنْتُمْ ‏","","",""],[1577,1577,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا كَانَ الْوَبَاءُ بِأَرْضٍ وَلَسْتَ بِهَا فَلَا تَدْخُلْهَا وَإِذَا كَانَ بِأَرْضٍ وَأَنْتَ بِهَا فَلَا تَخْرُجْ مِنْهَا ‏","","",""],[1578,1578,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ قُسَيْطٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَنَّ قَوْمًا مِنْ ‏ ‏الْعَرَبِ ‏ ‏أَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏فَأَسْلَمُوا وَأَصَابَهُمْ وَبَاءُ ‏ ‏الْمَدِينَةِ ‏ ‏حُمَّاهَا ‏ ‏فَأُرْكِسُوا ‏ ‏فَخَرَجُوا مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏فَاسْتَقْبَلَهُمْ نَفَرٌ مِنْ أَصْحَابِهِ ‏ ‏يَعْنِي ‏ ‏أَصْحَابَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا لَهُمْ مَا لَكُمْ رَجَعْتُمْ قَالُوا أَصَابَنَا وَبَاءُ ‏ ‏الْمَدِينَةِ ‏ ‏فَاجْتَوَيْنَا ‏ ‏الْمَدِينَةَ ‏ ‏فَقَالُوا أَمَا لَكُمْ فِي رَسُولِ اللَّهِ ‏ ‏أُسْوَةٌ ‏ ‏فَقَالَ بَعْضُهُمْ نَافَقُوا وَقَالَ بَعْضُهُمْ لَمْ يُنَافِقُوا هُمْ مُسْلِمُونَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ وَاللَّهُ ‏ ‏أَرْكَسَهُمْ ‏ ‏بِمَا كَسَبُوا ‏} ‏الْآيَةَ ‏","","",""],[1579,1579,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَامِرِ بْنِ رَبِيعَةَ ‏ ‏قَالَ ‏ ‏سَمِعَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏صَوْتَ ‏ ‏ابْنِ الْمُغْتَرِفِ ‏ ‏أَوْ ‏ ‏ابْنِ الْغَرِفِ الْحَادِي ‏ ‏فِي جَوْفِ اللَّيْلِ وَنَحْنُ مُنْطَلِقُونَ إِلَى ‏ ‏مَكَّةَ ‏ ‏فَأَوْضَعَ ‏ ‏عُمَرُ ‏ ‏رَاحِلَتَهُ ‏ ‏حَتَّى دَخَلَ مَعَ الْقَوْمِ فَإِذَا هُوَ مَعَ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏فَلَمَّا طَلَعَ الْفَجْرُ قَالَ ‏ ‏عُمَرُ ‏ ‏هَيْءَ الْآنَ اسْكُتْ الْآنَ قَدْ طَلَعَ الْفَجْرُ اذْكُرُوا اللَّهَ قَالَ ثُمَّ أَبْصَرَ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏خُفَّيْنِ قَالَ وَخُفَّانِ فَقَالَ قَدْ ‏ ‏لَبِسْتُهُمَا مَعَ مَنْ هُوَ خَيْرٌ مِنْكَ ‏ ‏أَوْ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏عَزَمْتُ ‏ ‏عَلَيْكَ إِلَّا نَزَعْتَهُمَا فَإِنِّي أَخَافُ أَنْ يَنْظُرَ النَّاسُ إِلَيْكَ فَيَقْتَدُونَ بِكَ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَاه ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏فَذَكَرَهُ بِإِسْنَادِهِ ‏ ‏وَقَالَ ‏ ‏لَبِسْتُهُمَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1580,1580,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏قَالَ ‏ ‏أَقْطَعَنِي ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعُمَرَ بْنَ الْخَطَّابِ ‏ ‏أَرْضَ كَذَا وَكَذَا فَذَهَبَ ‏ ‏الزُّبَيْرُ ‏ ‏إِلَى آلِ ‏ ‏عُمَرَ ‏ ‏فَاشْتَرَى نَصِيبَهُ مِنْهُمْ فَأَتَى ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏فَقَالَ إِنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏زَعَمَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقْطَعَهُ ‏ ‏وَعُمَرَ بْنَ الْخَطَّابِ ‏ ‏أَرْضَ كَذَا وَكَذَا وَإِنِّي اشْتَرَيْتُ نَصِيبَ آلِ ‏ ‏عُمَرَ ‏ ‏فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏جَائِزُ الشَّهَادَةِ لَهُ وَعَلَيْهِ ‏","","",""],[1581,1581,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏ضَمْضَمِ بْنِ زُرْعَةَ ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ عُبَيْدٍ ‏ ‏يَرُدُّهُ إِلَى ‏ ‏مَالِكِ بْنِ يَخَامِرَ ‏ ‏عَنِ ‏ ‏ابْنِ السَّعْدِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَنْقَطِعُ الْهِجْرَةُ مَا دَامَ الْعَدُوُّ يُقَاتَلُ ‏ ‏فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏وَعَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ الْهِجْرَةَ خَصْلَتَانِ إِحْدَاهُمَا أَنْ تَهْجُرَ السَّيِّئَاتِ وَالْأُخْرَى أَنْ تُهَاجِرَ إِلَى اللَّهِ وَرَسُولِهِ وَلَا تَنْقَطِعُ الْهِجْرَةُ مَا تُقُبِّلَتْ التَّوْبَةُ وَلَا تَزَالُ التَّوْبَةُ مَقْبُولَةً حَتَّى تَطْلُعَ الشَّمْسُ مِنْ الْمَغْرِبِ فَإِذَا طَلَعَتْ طُبِعَ عَلَى كُلِّ قَلْبٍ بِمَا فِيهِ وَكُفِيَ النَّاسُ الْعَمَلَ ‏","","",""],[1582,1582,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏حَدَّثَنِي ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَالَ ‏ ‏لَمَّا خَرَجَ الْمَجُوسِيُّ مِنْ عِنْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلْتُهُ فَأَخْبَرَنِي أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيَّرَهُ بَيْنَ ‏ ‏الْجِزْيَةِ ‏ ‏وَالْقَتْلِ فَاخْتَارَ ‏ ‏الْجِزْيَةَ ‏","","",""],[1583,1583,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ يُوسُفُ بْنُ يَعْقُوبَ الْمَاجِشُونُ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ إِبْرَاهِيمَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنِّي لَوَاقِفٌ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فِي الصَّفِّ نَظَرْتُ عَنْ يَمِينِي وَعَنْ شِمَالِي فَإِذَا أَنَا بَيْنَ غُلَامَيْنِ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏حَدِيثَةٍ أَسْنَانُهُمَا تَمَنَّيْتُ لَوْ كُنْتُ بَيْنَ ‏ ‏أَضْلَعَ ‏ ‏مِنْهُمَا فَغَمَزَنِي أَحَدُهُمَا فَقَالَ يَا عَمِّ هَلْ تَعْرِفُ ‏ ‏أَبَا جَهْلٍ ‏ ‏قَالَ قُلْتُ نَعَمْ وَمَا حَاجَتُكَ يَا ابْنَ أَخِي قَالَ بَلَغَنِي أَنَّهُ سَبَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ لَوْ رَأَيْتُهُ لَمْ يُفَارِقْ ‏ ‏سَوَادِي ‏ ‏سَوَادَهُ ‏ ‏حَتَّى يَمُوتَ ‏ ‏الْأَعْجَلُ ‏ ‏مِنَّا قَالَ فَغَمَزَنِي الْآخَرُ فَقَالَ لِي مِثْلَهَا قَالَ فَتَعَجَّبْتُ لِذَلِكَ قَالَ فَلَمْ ‏ ‏أَنْشَبْ ‏ ‏أَنْ نَظَرْتُ إِلَى ‏ ‏أَبِي جَهْلٍ ‏ ‏يَجُولُ فِي النَّاسِ فَقُلْتُ لَهُمَا أَلَا تَرَيَانِ هَذَا صَاحِبُكُمَا الَّذِي تَسْأَلَانِ عَنْهُ ‏ ‏فَابْتَدَرَاهُ ‏ ‏فَاسْتَقْبَلَهُمَا فَضَرَبَاهُ حَتَّى قَتَلَاهُ ثُمَّ انْصَرَفَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَاهُ فَقَالَ ‏ ‏أَيُّكُمَا قَتَلَهُ فَقَالَ كُلُّ وَاحِدٍ مِنْهُمَا أَنَا قَتَلْتُهُ قَالَ هَلْ مَسَحْتُمَا سَيْفَيْكُمَا قَالَا لَا فَنَظَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي السَّيْفَيْنِ فَقَالَ كِلَاكُمَا قَتَلَهُ وَقَضَى ‏ ‏بِسَلَبِهِ ‏ ‏لِمُعَاذِ بْنِ عَمْرِو بْنِ الْجَمُوحِ ‏ ‏وَهُمَا ‏ ‏مُعَاذُ بْنُ عَمْرِو بْنِ الْجَمُوحِ ‏ ‏وَمُعَاذُ ابْنُ عَفْرَاءَ ‏","","",""],[1584,1584,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏قَاصُّ ‏ ‏أَهْلِ ‏ ‏فِلَسْطِينَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثٌ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ إِنْ كُنْتُ لَحَالِفًا عَلَيْهِنَّ لَا يَنْقُصُ مَالٌ مِنْ ‏ ‏صَدَقَةٍ ‏ ‏فَتَصَدَّقُوا وَلَا ‏ ‏يَعْفُو عَبْدٌ عَنْ مَظْلَمَةٍ ‏ ‏يَبْتَغِي ‏ ‏بِهَا وَجْهَ اللَّهِ إِلَّا رَفَعَهُ اللَّهُ بِهَا ‏ ‏و قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏إِلَّا زَادَهُ اللَّهُ بِهَا عِزًّا يَوْمَ الْقِيَامَةِ وَلَا يَفْتَحُ عَبْدٌ بَابَ مَسْأَلَةٍ إِلَّا فَتَحَ اللَّهُ عَلَيْهِ بَابَ فَقْرٍ ‏","","",""],[1585,1585,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ الدَّرَاوَرْدِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعُمَرُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعَلِيٌّ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعُثْمَانُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَطَلْحَةُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَالزُّبَيْرُ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَعَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَسَعْدُ بْنُ أَبِي وَقَّاصٍ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَسَعِيدُ بْنُ زَيْدِ بْنِ عَمْرِو بْنِ نُفَيْلٍ ‏ ‏فِي الْجَنَّةِ ‏ ‏وَأَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ ‏ ‏فِي الْجَنَّةِ ‏","","",""],[1586,1586,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِسْحَاقَ يَعْنِي عَبْدَ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهِدْتُ غُلَامًا مَعَ عُمُومَتِي ‏ ‏حِلْفَ الْمُطَيَّبِينَ ‏ ‏فَمَا أُحِبُّ أَنَّ لِي حُمْرَ النَّعَمِ وَأَنِّي أَنْكُثُهُ ‏","","",""],[1587,1587,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مَكْحُولٌ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فَشَكَّ فِي صَلَاتِهِ فَإِنْ شَكَّ فِي الْوَاحِدَةِ وَالثِّنْتَيْنِ فَلْيَجْعَلْهُمَا وَاحِدَةً وَإِنْ شَكَّ فِي الثِّنْتَيْنِ وَالثَّلَاثِ فَلْيَجْعَلْهُمَا ثِنْتَيْنِ وَإِنْ شَكَّ فِي الثَّلَاثِ وَالْأَرْبَعِ فَلْيَجْعَلْهُمَا ثَلَاثًا حَتَّى يَكُونَ الْوَهْمُ فِي الزِّيَادَةِ ثُمَّ يَسْجُدْ سَجْدَتَيْنِ قَبْلَ أَنْ يُسَلِّمَ ثُمَّ يُسَلِّمْ ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏وَقَالَ ‏ ‏لِي ‏ ‏حُسَيْنُ بْنُ عَبْدِ اللَّهِ ‏ ‏هَلْ أَسْنَدَهُ لَكَ فَقُلْتُ لَا فَقَالَ لَكِنَّهُ ‏ ‏حَدَّثَنِي أَنَّ ‏ ‏كُرَيْبًا ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏حَدَّثَهُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏جَلَسْتُ إِلَى ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏فَقَالَ يَا ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏إِذَا اشْتَبَهَ عَلَى الرَّجُلِ فِي صَلَاتِهِ فَلَمْ يَدْرِ أَزَادَ أَمْ نَقَصَ قُلْتُ وَاللَّهِ يَا أَمِيرَ الْمُؤْمِنِينَ مَا أَدْرِي مَا سَمِعْتُ فِي ذَلِكَ شَيْئًا فَقَالَ ‏ ‏عُمَرُ ‏ ‏وَاللَّهِ مَا أَدْرِي قَالَ فَبَيْنَا نَحْنُ عَلَى ذَلِكَ إِذْ جَاءَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏فَقَالَ مَا هَذَا الَّذِي تَذَاكَرَانِ فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏ذَكَرْنَا الرَّجُلَ يَشُكُّ فِي صَلَاتِهِ كَيْفَ يَصْنَعُ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ هَذَا الْحَدِيثَ ‏","","",""],[1588,1588,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاحٌ ‏ ‏وَيَزِيدُ ‏ ‏الْمَعْنَى ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَامِرِ بْنِ رَبِيعَةَ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏أَخْبَرَ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏وَهُوَ يَسِيرُ فِي طَرِيقِ ‏ ‏الشَّامِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ هَذَا ‏ ‏السَّقَمَ ‏ ‏عُذِّبَ بِهِ الْأُمَمُ قَبْلَكُمْ فَإِذَا سَمِعْتُمْ بِهِ فِي أَرْضٍ فَلَا تَدْخُلُوهَا عَلَيْهِ وَإِذَا وَقَعَ بِأَرْضٍ وَأَنْتُمْ بِهَا فَلَا تَخْرُجُوا فِرَارًا مِنْهُ ‏ ‏قَالَ ‏ ‏فَرَجَعَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏مِنْ ‏ ‏الشَّامِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ زَيْدِ بْنِ الْخَطَّابِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏خَرَجَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏يُرِيدُ ‏ ‏الشَّامَ ‏ ‏فَذَكَرَ الْحَدِيثَ قَالَ وَكَانَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏غَائِبًا فَجَاءَ فَقَالَ إِنَّ عِنْدِي مِنْ هَذَا عِلْمًا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا سَمِعْتُمْ بِهِ فِي أَرْضٍ فَلَا تَقْدَمُوا عَلَيْهِ وَإِذَا ‏ ‏وَقَعَ ‏ ‏بِأَرْضٍ وَأَنْتُمْ بِهَا فَلَا تَخْرُجُوا فِرَارًا مِنْهُ ‏","","",""],[1589,1589,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا الرَّدَّادِ اللَّيْثِيَّ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَنَا الرَّحْمَنُ خَلَقْتُ ‏ ‏الرَّحِمَ ‏ ‏وَشَقَقْتُ لَهَا مِنْ اسْمِي اسْمًا فَمَنْ ‏ ‏وَصَلَهَا ‏ ‏وَصَلْتُهُ ‏ ‏وَمَنْ قَطَعَهَا ‏ ‏بَتَتُّهُ ‏","","",""],[1590,1590,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ شُعَيْبِ بْنِ أَبِي حَمْزَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا الرَّدَّادِ اللَّيْثِيَّ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَنَا الرَّحْمَنُ وَأَنَا خَلَقْتُ ‏ ‏الرَّحِمَ ‏ ‏وَاشْتَقَقْتُ لَهَا مِنْ اسْمِي فَمَنْ ‏ ‏وَصَلَهَا ‏ ‏وَصَلَهُ ‏ ‏اللَّهُ وَمَنْ قَطَعَهَا ‏ ‏بَتَتُّهُ ‏","","",""],[1591,1591,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَامِرِ بْنِ رَبِيعَةَ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏خَرَجَ إِلَى ‏ ‏الشَّامِ ‏ ‏فَلَمَّا جَاءَ ‏ ‏سَرْغَ ‏ ‏بَلَغَهُ أَنَّ الْوَبَاءَ قَدْ وَقَعَ ‏ ‏بِالشَّامِ ‏ ‏فَأَخْبَرَهُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعْتُمْ بِهِ بِأَرْضٍ فَلَا تَقْدَمُوا عَلَيْهِ وَإِذَا وَقَعَ بِأَرْضٍ وَأَنْتُمْ بِهَا فَلَا تَخْرُجُوا فِرَارًا مِنْهُ فَرَجَعَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏مِنْ ‏ ‏سَرْغَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ زَيْدِ بْنِ الْخَطَّابِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏خَرَجَ إِلَى ‏ ‏الشَّامِ ‏ ‏حَتَّى إِذَا كَانَ ‏ ‏بِسَرْغَ ‏ ‏لَقِيَهُ أُمَرَاءُ الْأَجْنَادِ ‏ ‏أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ ‏ ‏وَأَصْحَابُهُ فَأَخْبَرُوهُ أَنَّ الْوَبَاءَ قَدْ وَقَعَ ‏ ‏بِالشَّامِ ‏ ‏فَذَكَرَ الْحَدِيثَ قَالَ فَجَاءَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏وَكَانَ مُتَغَيِّبًا فِي بَعْضِ حَاجَتِهِ فَقَالَ إِنَّ عِنْدِي مِنْ هَذَا عِلْمًا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا كَانَ بِأَرْضٍ وَأَنْتُمْ بِهَا فَلَا تَخْرُجُوا فِرَارًا مِنْهُ وَإِذَا سَمِعْتُمْ بِهِ بِأَرْضٍ فَلَا تَقْدَمُوا عَلَيْهِ قَالَ فَحَمِدَ اللَّهَ ‏ ‏عُمَرُ ‏ ‏ثُمَّ انْصَرَفَ ‏","","",""],[1592,1592,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْعَلَاءِ الْحَسَنُ بْنُ سَوَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا سَمِعْتُمْ بِهِ بِأَرْضٍ وَلَسْتُمْ بِهَا فَلَا تَدْخُلُوهَا وَإِذَا وَقَعَ وَأَنْتُمْ فِيهَا فَلَا تَخْرُجُوا فِرَارًا مِنْهَا ‏","","",""],[1593,1593,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏بَجَالَةَ التَّمِيمِيِّ ‏ ‏قَالَ ‏ ‏لَمْ يُرِدْ ‏ ‏عُمَرُ ‏ ‏أَنْ يَأْخُذَ الْجِزْيَةَ مِنْ ‏ ‏الْمَجُوسِ ‏ ‏حَتَّى شَهِدَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذَهَا مِنْ ‏ ‏مَجُوسِ هَجَرَ ‏","","",""],[1594,1594,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏اشْتَكَى ‏ ‏أَبُو الرَّدَّادِ ‏ ‏فَعَادَهُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏فَقَالَ ‏ ‏أَبُو الرَّدَّادِ ‏ ‏خَيْرُهُمْ ‏ ‏وَأَوْصَلُهُمْ مَا عَلِمْتُ ‏ ‏أَبُو مُحَمَّدٍ ‏ ‏فَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَنَا اللَّهُ وَأَنَا الرَّحْمَنُ خَلَقْتُ ‏ ‏الرَّحِمَ ‏ ‏وَشَقَقْتُ لَهَا مِنْ اسْمِي فَمَنْ ‏ ‏وَصَلَهَا ‏ ‏وَصَلْتُهُ ‏ ‏وَمَنْ قَطَعَهَا ‏ ‏بَتَتُّهُ ‏","","",""],[1595,1595,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ قَارِظٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّهُ دَخَلَ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏وَهُوَ مَرِيضٌ فَقَالَ لَهُ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَصَلَتْكَ رَحِمٌ إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَنَا الرَّحْمَنُ وَخَلَقْتُ الرَّحِمَ وَشَقَقْتُ لَهَا مِنْ اسْمِي فَمَنْ ‏ ‏يَصِلْهَا ‏ ‏أَصِلْهُ ‏ ‏وَمَنْ يَقْطَعْهَا أَقْطَعْهُ ‏ ‏أَوْ قَالَ مَنْ يَبُتَّهَا أَبْتُتْهُ ‏","","",""],[1596,1596,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏نُوحُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏نَصْرِ بْنِ عَلِيٍّ الْجَهْضَمِيِّ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ شَيْبَانَ الْحُدَّانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏قُلْتُ لَهُ أَلَا تُحَدِّثُنِي حَدِيثًا عَنْ ‏ ‏أَبِيكَ ‏ ‏سَمِعَهُ أَبُوكَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ أَقْبَلَ رَمَضَانُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ رَمَضَانَ شَهْرٌ افْتَرَضَ اللَّهُ عَزَّ وَجَلَّ صِيَامَهُ وَإِنِّي سَنَنْتُ لِلْمُسْلِمِينَ قِيَامَهُ فَمَنْ صَامَهُ إِيمَانًا وَاحْتِسَابًا خَرَجَ مِنْ الذُّنُوبِ كَيَوْمِ وَلَدَتْهُ أُمُّهُ ‏","","",""],[1597,1597,"","","‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ أَحْمَدُ بْنُ جَعْفَرِ بْنِ حِمْدَانَ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَجَدْتُ هَذَا الْحَدِيثَ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ مُسْلِمٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ كَانَ يُذَاكِرُ ‏ ‏عُمَرَ ‏ ‏شَأْنَ الصَّلَاةِ فَانْتَهَى إِلَيْهِمْ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏فَقَالَ أَلَا أُحَدِّثُكُمْ بِحَدِيثٍ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا بَلَى قَالَ فَأَشْهَدُ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ صَلَّى صَلَاةً يَشُكُّ فِي النُّقْصَانِ فَلْيُصَلِّ حَتَّى يَشُكَّ فِي الزِّيَادَةِ ‏ ‏آخِرُ أَحَادِيثِ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[1598,1598,"","","‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ الرَّبِيعِ أَبُو خِدَاشٍ ‏ ‏حَدَّثَنَا ‏ ‏وَاصِلٌ ‏ ‏مَوْلَى ‏ ‏أَبِي عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏بَشَّارِ بْنِ أَبِي سَيْفٍ الْجَرْمِيِّ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ غُطَيْفٍ ‏ ‏قَالَ ‏ ‏دَخَلْنَا عَلَى ‏ ‏أَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ ‏ ‏نَعُودُهُ ‏ ‏مِنْ ‏ ‏شَكْوًى ‏ ‏أَصَابَهُ وَامْرَأَتُهُ ‏ ‏تُحَيْفَةُ ‏ ‏قَاعِدَةٌ عِنْدَ رَأْسِهِ قُلْتُ كَيْفَ بَاتَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏قَالَتْ وَاللَّهِ لَقَدْ بَاتَ بِأَجْرٍ فَقَالَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏مَا بِتُّ بِأَجْرٍ وَكَانَ مُقْبِلًا بِوَجْهِهِ عَلَى الْحَائِطِ فَأَقْبَلَ عَلَى الْقَوْمِ بِوَجْهِهِ فَقَالَ أَلَا تَسْأَلُونَنِي عَمَّا قُلْتُ قَالُوا مَا أَعْجَبَنَا مَا قُلْتَ فَنَسْأَلُكَ عَنْهُ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَنْفَقَ نَفَقَةً فَاضِلَةً فِي سَبِيلِ اللَّهِ فَبِسَبْعِ مِائَةٍ وَمَنْ أَنْفَقَ عَلَى نَفْسِهِ وَأَهْلِهِ أَوْ عَادَ مَرِيضًا أَوْ مَازَ أَذًى فَالْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا وَالصَّوْمُ جُنَّةٌ مَا لَمْ ‏ ‏يَخْرِقْهَا ‏ ‏وَمَنْ ابْتَلَاهُ اللَّهُ بِبَلَاءٍ فِي جَسَدِهِ فَهُوَ لَهُ ‏ ‏حِطَّةٌ ‏","","",""],[1599,1599,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مَيْمُونٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدُ بْنُ سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏قَالَ ‏ ‏آخِرُ مَا تَكَلَّمَ بِهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْرِجُوا ‏ ‏يَهُودَ ‏ ‏أَهْلِ ‏ ‏الْحِجَازِ ‏ ‏وَأَهْلِ ‏ ‏نَجْرَانَ ‏ ‏مِنْ ‏ ‏جَزِيرَةِ الْعَرَبِ ‏ ‏وَاعْلَمُوا أَنَّ شِرَارَ النَّاسِ الَّذِينَ اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏","","",""],[1600,1600,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سُرَاقَةَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏ذَكَرَ ‏ ‏الدَّجَّالَ ‏ ‏فَحَلَّاهُ بِحِلْيَةٍ لَا أَحْفَظُهَا قَالُوا يَا رَسُولَ اللَّهِ كَيْفَ قُلُوبُنَا يَوْمَئِذٍ كَالْيَوْمِ فَقَالَ أَوْ خَيْرٌ ‏","","",""]];
